-- ==============================================================================
-- Qurio: Catálogo Semilla de Rutas, Módulos, Ejercicios y Logros
-- ==============================================================================

-- 1. Rutas Formativas
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty,
  estimated_hours = EXCLUDED.estimated_hours,
  badge_reward = EXCLUDED.badge_reward;

-- 2. Módulos
ON CONFLICT (path_id, module_number) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description;


-- 3. Ejercicios (80 Retos Calibrados en las 4 Rutas Formativas)
SELECT ', 'SELECT nombre_producto, precio FROM productos;', 30, 'Principiante', FALSE, 1),
('e0000000-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000001', 'Cálculo de precios con IVA', 'Calcula el precio final con impuestos para cada producto. Muestra el `nombre_producto`, el `precio` original y calcula el precio con el 21% de IVA (`precio * 1.21`) redondeado a 2 decimales, llamando a esa nueva columna `precio_con_iva`.', '-- Muestra columnas y calcula el precio con IVA
SELECT ', 'SELECT nombre_producto, precio, ROUND(precio * 1.21, 2) AS precio_con_iva FROM productos;', 35, 'Principiante', FALSE, 2),
('e0000000-0000-0000-0000-000000000019', 'a0000000-0000-0000-0000-000000000001', 'Concatenación de nombre completo', 'Prepara un directorio para el equipo de atención al cliente. Une el `nombre` y el `apellido` de cada cliente separados por un espacio, nómbralo `cliente_completo`, y muestra también su `email` desde la tabla `clientes`.', '-- Concatena nombre y apellido con un espacio
SELECT ', 'SELECT nombre || '' '' || apellido AS cliente_completo, email FROM clientes;', 35, 'Principiante', FALSE, 3),
('e0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000001', 'Catálogo de ciudades únicas (DISTINCT)', 'Logística necesita saber en qué ciudades tenemos clientes sin que los nombres se repitan. Obtén la lista de ciudades únicas (`ciudad`) de la tabla `clientes`.', '-- Obtén valores únicos de ciudad
SELECT ', 'SELECT DISTINCT ciudad FROM clientes;', 35, 'Principiante', FALSE, 4),
('e0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'Productos premium (> 500€)', 'El equipo de marketing prepara una campaña especial de productos exclusivos. Muestra el `nombre_producto`, el `precio` y el `stock` de aquellos productos cuyo precio sea mayor a 500€.', '-- Filtra los productos de alto valor
SELECT ', 'SELECT nombre_producto, precio, stock FROM productos WHERE precio > 500;', 35, 'Principiante', FALSE, 5),
('e0000000-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000002', 'Productos en rango medio (BETWEEN)', 'Encuentra los productos de gama media para una promoción especial. Muestra el `nombre_producto` y el `precio` de todos los artículos cuyo precio esté entre 100€ y 800€ (ambos inclusive).', '-- Filtra productos en el rango de 100 a 800
SELECT ', 'SELECT nombre_producto, precio FROM productos WHERE precio BETWEEN 100 AND 800;', 35, 'Principiante', FALSE, 6),
('e0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000002', 'Búsqueda por patrón de correo (LIKE)', 'Marketing quiere enviar un aviso a los usuarios registrados con correos corporativos estándar `@email.com`. Muestra el `nombre`, `apellido` y `email` de aquellos clientes cuyo correo termine exactamente en `@email.com`.', '-- Filtra clientes con comodín LIKE
SELECT ', 'SELECT nombre, apellido, email FROM clientes WHERE email LIKE ''%@email.com'';', 40, 'Principiante', FALSE, 7),
('e0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000002', 'Filtro de ciudades específicas (IN)', 'Operaciones lanzó envíos express para tres ciudades clave: Madrid, Barcelona y Valencia. Muestra el `cliente_id`, `nombre`, `apellido` y `ciudad` de los clientes que vivan en cualquiera de estas tres ciudades.', '-- Filtra con el operador IN
SELECT ', 'SELECT cliente_id, nombre, apellido, ciudad FROM clientes WHERE ciudad IN (''Madrid'', ''Barcelona'', ''Valencia'');', 40, 'Principiante', FALSE, 8),
('e0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000002', 'Productos en riesgo de stock (OR)', 'El almacén necesita ubicar productos en situación crítica de inventario: artículos con muy poco stock (15 o menos unidades) o artículos con sobrestock (75 o más unidades). Muestra el `producto_id`, `nombre_producto` y `stock` que cumplan cualquiera de estas dos condiciones.', '-- Combina condiciones con OR
SELECT ', 'SELECT producto_id, nombre_producto, stock FROM productos WHERE stock <= 15 OR stock >= 75;', 40, 'Principiante', FALSE, 9),
('e0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000002', 'Facturas de alto valor no pagadas (AND + NOT)', 'Contabilidad necesita revisar facturas importantes pendientes de cobro. Muestra el `factura_id`, `monto_total` y `estado_factura` de aquellas facturas con un monto de 400€ o más y cuyo estado sea distinto de `''pagada''`.', '-- Combina AND con el operador de desigualdad
SELECT ', 'SELECT factura_id, monto_total, estado_factura FROM facturas WHERE monto_total >= 400 AND estado_factura <> ''pagada'';', 45, 'Principiante', FALSE, 10),
('e0000000-0000-0000-0000-000000000078', 'a0000000-0000-0000-0000-000000000002', 'Combinación de condiciones con paréntesis ((OR) + AND)', 'Marketing busca lanzar una oferta sobre equipos de cómputo y pantallas con precio accesible. Muestra `producto_id`, `categoria_id`, `nombre_producto`, `precio` y `stock` de los artículos de la tabla `productos` que pertenezcan a la categoría `1` o a la categoría `2`, y que además tengan un `precio` menor a `1000`€. Ordena por `producto_id` ascendente.', '-- Agrupa la disyunción OR entre paréntesis antes de aplicar AND
SELECT ', 'SELECT producto_id, categoria_id, nombre_producto, precio, stock FROM productos WHERE (categoria_id = 1 OR categoria_id = 2) AND precio < 1000 ORDER BY producto_id ASC;', 45, 'Principiante', TRUE, 11),
('e0000000-0000-0000-0000-000000000077', 'a0000000-0000-0000-0000-000000000002', 'Proveedores sin teléfono registrado (IS NULL)', 'Compras detectó que algunas fichas de fabricantes quedaron incompletas al darse de alta. Muestra el `proveedor_id`, `nombre_proveedor` y `pais` de aquellos registros de la tabla `proveedores` cuyo `telefono` no haya sido cargado (`NULL`).', '-- Detecta valores ausentes en una columna con IS NULL
SELECT ', 'SELECT proveedor_id, nombre_proveedor, pais FROM proveedores WHERE telefono IS NULL;', 40, 'Principiante', FALSE, 12),
('e0000000-0000-0000-0000-000000000051', 'a0000000-0000-0000-0000-000000000002', 'Pedidos de febrero de 2024 (fechas con BETWEEN)', 'Auditoría quiere revisar todas las compras registradas durante febrero de 2024. Muestra el `pedido_id`, `cliente_id`, `fecha_pedido` y `total` de los pedidos realizados entre `''2024-02-01''` y `''2024-02-29''` (ambos inclusive), ordenados cronológicamente por `fecha_pedido ASC` y, en caso de empate, por `pedido_id ASC`.', '-- Filtra por rango de fechas en WHERE
SELECT ', 'SELECT pedido_id, cliente_id, fecha_pedido, total FROM pedidos WHERE fecha_pedido BETWEEN ''2024-02-01'' AND ''2024-02-29'' ORDER BY fecha_pedido ASC, pedido_id ASC;', 40, 'Principiante', TRUE, 13),
('e0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000003', 'Clientes españoles ordenados por apellido', 'Organiza la lista de clientes que viven en España por orden alfabético. Muestra su `nombre`, `apellido` y `ciudad` de la tabla `clientes`, ordenando los resultados alfabéticamente por su `apellido` (de la A a la Z) y, en caso de empate, por `cliente_id` ascendente.', '-- Filtra y ordena los clientes
SELECT ', 'SELECT nombre, apellido, ciudad FROM clientes WHERE pais = ''España'' ORDER BY apellido ASC, cliente_id ASC;', 40, 'Principiante', TRUE, 14),
('e0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000003', 'Los 5 productos con menor stock', 'El almacén necesita reponer con urgencia los artículos que están por agotarse. Muestra el `nombre_producto` y el `stock` de los 5 productos con menor cantidad disponible, ordenando por `stock` ascendente y desempatando por `producto_id` ascendente.', '-- Ordena y limita a los 5 productos con menos stock
SELECT ', 'SELECT nombre_producto, stock FROM productos ORDER BY stock ASC, producto_id ASC LIMIT 5;', 40, 'Principiante', TRUE, 15),
('e0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000003', 'Ordenamiento Multi-Criterio', 'Organiza los productos por su categoría y luego por su valor comercial. Muestra `producto_id`, `categoria_id`, `nombre_producto` y `precio`, ordenándolos primero por categoría de menor a mayor (`categoria_id ASC`), y dentro de cada categoría, del más caro al más barato (`precio DESC`).', '-- Ordena por múltiples columnas
SELECT ', 'SELECT producto_id, categoria_id, nombre_producto, precio FROM productos ORDER BY categoria_id ASC, precio DESC;', 45, 'Principiante', TRUE, 16),
('e0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000003', 'Paginación de clientes (OFFSET)', 'Simula la paginación de un panel web que muestra 5 clientes por página. Obtén los clientes de la segunda página mostrando `cliente_id`, `nombre` y `email`, ordenados por `cliente_id ASC`, saltando los primeros 5 registros y mostrando los siguientes 5.', '-- Usa LIMIT y OFFSET para paginar
SELECT ', 'SELECT cliente_id, nombre, email FROM clientes ORDER BY cliente_id ASC LIMIT 5 OFFSET 5;', 45, 'Principiante', TRUE, 17),
('e0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000004', 'Métricas globales de ventas', 'Genera un resumen ejecutivo de las ventas completadas. Calcula el número de pedidos bajo el nombre `total_pedidos`, la suma total de dinero bajo `ingresos_totales` y el promedio de compra redondeado a 2 decimales bajo `ticket_promedio`, tomando solo los pedidos con estado `''completado''`.', '-- Agrega las métricas globales para pedidos completados
SELECT ', 'SELECT COUNT(*) AS total_pedidos, SUM(total) AS ingresos_totales, ROUND(AVG(total), 2) AS ticket_promedio FROM pedidos WHERE estado_pedido = ''completado'';', 45, 'Principiante', FALSE, 18),
('e0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000004', 'Rango de precios por categoría (MAX/MIN)', 'Analiza la diferencia de precios en cada departamento. Muestra el `categoria_id`, el precio más bajo bajo el nombre `precio_minimo` y el precio más alto bajo `precio_maximo` para cada categoría de productos.', '-- Calcula precios extremos por categoría
SELECT ', 'SELECT categoria_id, MIN(precio) AS precio_minimo, MAX(precio) AS precio_maximo FROM productos GROUP BY categoria_id;', 45, 'Principiante', FALSE, 19),
('e0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000004', 'Distribución de clientes por país', '¿De qué países son nuestros clientes? Muestra la columna `pais` y el número total de clientes en cada país bajo el nombre `total_clientes`, ordenando la lista de mayor a menor número de clientes y, en caso de empate, alfabéticamente por `pais`.', '-- Agrupa clientes por país
SELECT ', 'SELECT pais, COUNT(*) AS total_clientes FROM clientes GROUP BY pais ORDER BY total_clientes DESC, pais ASC;', 45, 'Principiante', TRUE, 20),
('e0000000-0000-0000-0000-000000000029', 'a0000000-0000-0000-0000-000000000004', 'Stock total por proveedor', 'Calcula el volumen total de productos que nos suministra cada fabricante. Muestra el `proveedor_id` y la suma de unidades disponibles en stock bajo el nombre `stock_total` desde la tabla `productos`.', '-- Suma el stock por proveedor
SELECT ', 'SELECT proveedor_id, SUM(stock) AS stock_total FROM productos GROUP BY proveedor_id;', 45, 'Principiante', FALSE, 21),
('e0000000-0000-0000-0000-000000000052', 'a0000000-0000-0000-0000-000000000004', 'Compras completadas por cliente (WHERE + GROUP BY)', 'Analiza únicamente las compras efectivas por cliente sin mezclar pedidos cancelados ni pendientes. Filtra los pedidos con `estado_pedido = ''completado''`, agrupa por `cliente_id` y muestra el `cliente_id`, el número de compras como `compras_completadas` y su suma como `gasto_completado`. Ordena de mayor a menor `gasto_completado` y desempata por `cliente_id` ascendente.', '-- Filtra filas individuales antes de agrupar
SELECT ', 'SELECT cliente_id, COUNT(*) AS compras_completadas, SUM(total) AS gasto_completado FROM pedidos WHERE estado_pedido = ''completado'' GROUP BY cliente_id ORDER BY gasto_completado DESC, cliente_id ASC;', 45, 'Principiante', TRUE, 22),
('e0000000-0000-0000-0000-000000000032', 'a0000000-0000-0000-0000-000000000004', 'Resumen de pedidos por estado', 'Construye un resumen de pedidos por estado. Muestra el `estado_pedido`, la cantidad de pedidos bajo el nombre `total_pedidos` y la suma acumulada de dinero bajo `monto_acumulado`, agrupando por estado y ordenando del estado con mayor dinero al de menor dinero (desempatando por `estado_pedido` ascendente).', '-- Resumen consolidado por estado de pedido
SELECT ', 'SELECT estado_pedido, COUNT(*) AS total_pedidos, SUM(total) AS monto_acumulado FROM pedidos GROUP BY estado_pedido ORDER BY monto_acumulado DESC, estado_pedido ASC;', 50, 'Principiante', TRUE, 23),
('e0000000-0000-0000-0000-000000000079', 'a0000000-0000-0000-0000-000000000004', 'Pedidos totales vs. compradores únicos (COUNT DISTINCT)', 'Un mismo cliente puede haber realizado varios pedidos, por lo que contar filas no equivale a contar personas. Para cada `estado_pedido` en la tabla `pedidos`, muestra el `estado_pedido`, la cantidad total de órdenes como `total_pedidos` (`COUNT(*)`) y cuántos clientes diferentes participaron como `clientes_unicos` (`COUNT(DISTINCT cliente_id)`). Ordena de mayor a menor `total_pedidos` y desempata por `estado_pedido` ascendente.', '-- Compara el total de operaciones frente a sujetos únicos por estado
SELECT ', 'SELECT estado_pedido, COUNT(*) AS total_pedidos, COUNT(DISTINCT cliente_id) AS clientes_unicos FROM pedidos GROUP BY estado_pedido ORDER BY total_pedidos DESC, estado_pedido ASC;', 50, 'Principiante', TRUE, 24),
('e0000000-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000004', 'Conteo de productos por categoría', '¿Cuántos productos tenemos en cada categoría? Muestra el `categoria_id` y el número total de productos bajo el nombre `total_productos`, mostrando únicamente aquellas categorías que tengan más de 2 productos.', '-- Utiliza GROUP BY y HAVING
SELECT ', 'SELECT categoria_id, COUNT(*) AS total_productos FROM productos GROUP BY categoria_id HAVING COUNT(*) > 2;', 45, 'Principiante', FALSE, 25),
('e0000000-0000-0000-0000-000000000030', 'a0000000-0000-0000-0000-000000000004', 'Proveedores de alto volumen (HAVING SUM)', 'Identifica a nuestros proveedores más importantes en volumen. Muestra el `proveedor_id` y su stock total bajo el nombre `stock_total`, mostrando únicamente a aquellos proveedores cuyo stock total acumulado supere las 100 unidades.', '-- Filtra grupos con HAVING
SELECT ', 'SELECT proveedor_id, SUM(stock) AS stock_total FROM productos GROUP BY proveedor_id HAVING SUM(stock) > 100;', 50, 'Principiante', FALSE, 26),
('e0000000-0000-0000-0000-000000000031', 'a0000000-0000-0000-0000-000000000004', 'Clientes con compra promedio alta (HAVING AVG)', 'Encuentra a los clientes que hacen compras de alto valor promedio. Muestra el `cliente_id` y su importe promedio de compra redondeado a 2 decimales bajo el nombre `ticket_promedio`, mostrando solo a aquellos clientes cuyo promedio de compras supere los 500€.', '-- Filtra clientes por compra promedio
SELECT ', 'SELECT cliente_id, ROUND(AVG(total), 2) AS ticket_promedio FROM pedidos GROUP BY cliente_id HAVING AVG(total) > 500;', 50, 'Principiante', FALSE, 27),
('e0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000005', 'Pedidos con identidad del cliente', 'Descubre qué cliente realizó cada pedido. Cruza las tablas `pedidos` y `clientes` por su identificador común y muestra el `pedido_id`, el `nombre` del cliente, su `apellido` y el `total` del pedido.', '-- Cruza clientes con sus respectivos pedidos
SELECT ', 'SELECT p.pedido_id, c.nombre, c.apellido, p.total FROM pedidos p INNER JOIN clientes c ON p.cliente_id = c.cliente_id;', 45, 'Intermedio', FALSE, 28),
('e0000000-0000-0000-0000-000000000033', 'b0000000-0000-0000-0000-000000000005', 'Catálogo con nombre de categoría', 'Haz que el catálogo de productos sea legible mostrando el nombre de la categoría en lugar de su código numérico. Cruza `productos` con `categorias` y muestra `producto_id`, `nombre_producto`, `nombre_categoria` y `precio`. Ordena primero por categoría (A-Z) y luego por producto (A-Z).', '-- Cruza productos con categorias
SELECT ', 'SELECT p.producto_id, p.nombre_producto, c.nombre_categoria, p.precio FROM productos p INNER JOIN categorias c ON p.categoria_id = c.categoria_id ORDER BY c.nombre_categoria ASC, p.nombre_producto ASC;', 45, 'Intermedio', TRUE, 29),
('e0000000-0000-0000-0000-000000000034', 'b0000000-0000-0000-0000-000000000005', 'Productos y sus proveedores directos', 'Compras necesita saber de qué país proviene cada producto. Cruza `productos` con `proveedores` y muestra `producto_id`, `nombre_producto`, `nombre_proveedor` y el país del proveedor bajo el nombre `pais_proveedor`. Ordena los productos alfabéticamente y, en caso de empate, por `producto_id` ascendente.', '-- Relaciona productos con sus proveedores
SELECT ', 'SELECT pr.producto_id, pr.nombre_producto, pv.nombre_proveedor, pv.pais AS pais_proveedor FROM productos pr INNER JOIN proveedores pv ON pr.proveedor_id = pv.proveedor_id ORDER BY pr.nombre_producto ASC, pr.producto_id ASC;', 45, 'Intermedio', TRUE, 30),
('e0000000-0000-0000-0000-000000000035', 'b0000000-0000-0000-0000-000000000005', 'Facturación detallada con pagos aprobados', 'Concilia las facturas emitidas con sus pagos aprobados. Cruza `facturas` con `pagos` por `factura_id`, mostrando `factura_id`, el monto de la factura (`monto_total`), el `metodo_pago` y la `fecha_pago`, tomando únicamente los registros con `estado_pago = ''aprobado''`. Ordena por `factura_id` ascendente.', '-- Concilia facturas con pagos aprobados
SELECT ', 'SELECT f.factura_id, f.monto_total, pg.metodo_pago, pg.fecha_pago FROM facturas f INNER JOIN pagos pg ON f.factura_id = pg.factura_id WHERE pg.estado_pago = ''aprobado'' ORDER BY f.factura_id ASC;', 50, 'Intermedio', TRUE, 31),
('e0000000-0000-0000-0000-000000000012', 'b0000000-0000-0000-0000-000000000005', 'Gasto acumulado por cliente', 'Calcula cuánto dinero ha gastado en total cada uno de nuestros clientes. Cruza `clientes` y `pedidos`, y muestra el `cliente_id`, `nombre`, `apellido` y la suma de todas sus compras bajo el nombre `total_gastado`, ordenando de mayor a menor gasto y, en caso de empate, por `cliente_id` ascendente.', '-- Cruza clientes y pedidos y agrupa para sumar el gasto
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido, SUM(p.total) AS total_gastado FROM clientes c INNER JOIN pedidos p ON c.cliente_id = p.cliente_id GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY total_gastado DESC, c.cliente_id ASC;', 50, 'Intermedio', TRUE, 32),
('e0000000-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000006', 'Clientes sin compras registradas (LEFT JOIN & IS NULL)', '¿Qué clientes se han registrado pero nunca han realizado una compra? Haz un `LEFT JOIN` entre `clientes` y `pedidos` para mostrar el `cliente_id`, `nombre` y `apellido` de todos los usuarios sin pedidos registrados.', '-- Identifica clientes inactivos sin pedidos asociados
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c LEFT JOIN pedidos p ON c.cliente_id = p.cliente_id WHERE p.pedido_id IS NULL;', 50, 'Intermedio', FALSE, 33),
('e0000000-0000-0000-0000-000000000013', 'b0000000-0000-0000-0000-000000000006', 'Productos sin movimiento de venta', 'Detecta qué artículos del catálogo nunca han tenido ventas. Muestra el `producto_id` y `nombre_producto` de aquellos artículos que no tengan ninguna línea registrada en la tabla `detalle_pedidos`.', '-- Localiza productos sin ventas cruzando con detalle_pedidos
SELECT ', 'SELECT p.producto_id, p.nombre_producto FROM productos p LEFT JOIN detalle_pedidos dp ON p.producto_id = dp.producto_id WHERE dp.detalle_id IS NULL;', 50, 'Intermedio', FALSE, 34),
('e0000000-0000-0000-0000-000000000036', 'b0000000-0000-0000-0000-000000000006', 'Facturas pendientes de cobro (LEFT JOIN)', 'Tesorería necesita una lista de facturas emitidas que todavía no tienen ningún pago registrado. Haz un `LEFT JOIN` entre `facturas` y `pagos` para obtener `factura_id`, `pedido_id`, `fecha_emision` y `monto_total` de aquellas facturas sin ningún abono. Ordena por `factura_id` ascendente.', '-- Identifica facturas sin pagos registrados
SELECT ', 'SELECT f.factura_id, f.pedido_id, f.fecha_emision, f.monto_total FROM facturas f LEFT JOIN pagos p ON f.factura_id = p.factura_id WHERE p.pago_id IS NULL ORDER BY f.factura_id ASC;', 50, 'Intermedio', TRUE, 35),
('e0000000-0000-0000-0000-000000000037', 'b0000000-0000-0000-0000-000000000006', 'Productos fuera del almacén central (LEFT JOIN condicional)', 'El responsable del almacén central de Madrid (`almacen_id = 1`) quiere saber qué productos del catálogo NO disponen de existencias en ese almacén en particular. Conecta `productos` con `inventario` con un `LEFT JOIN` acotado al almacén 1 y muestra el `producto_id` y `nombre_producto` de los artículos ausentes en ese almacén, ordenados por `producto_id` ascendente.', '-- Detecta productos no inventariados en el almacén 1
SELECT ', 'SELECT p.producto_id, p.nombre_producto FROM productos p LEFT JOIN inventario i ON p.producto_id = i.producto_id AND i.almacen_id = 1 WHERE i.almacen_id IS NULL ORDER BY p.producto_id ASC;', 50, 'Intermedio', TRUE, 36),
('e0000000-0000-0000-0000-000000000038', 'b0000000-0000-0000-0000-000000000006', 'Censo completo de pedidos por cliente (preservando ceros)', 'Queremos una lista completa de todos los clientes y saber cuántos pedidos ha hecho cada uno, incluyendo con 0 a los que nunca han comprado. Muestra `cliente_id`, `nombre`, `apellido` y el total de compras bajo el nombre `total_pedidos` (usando `COUNT(p.pedido_id)`). Ordena por número de pedidos de mayor a menor y, en caso de empate, por `cliente_id` ascendente.', '-- Agrupa preservando clientes sin compras con COUNT(columna)
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido, COUNT(p.pedido_id) AS total_pedidos FROM clientes c LEFT JOIN pedidos p ON c.cliente_id = p.cliente_id GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY total_pedidos DESC, c.cliente_id ASC;', 50, 'Intermedio', TRUE, 37),
('e0000000-0000-0000-0000-000000000053', 'b0000000-0000-0000-0000-000000000006', 'Gasto total de clientes incluyendo 0€ (COALESCE)', 'Genera un reporte financiero con TODOS los clientes registrados y su gasto total acumulado, de modo que quienes nunca han comprado muestren `0` en lugar de `NULL`. Haz un `LEFT JOIN` entre `clientes` y `pedidos`, muestra `cliente_id`, `nombre`, `apellido` y `COALESCE(SUM(p.total), 0)` como `gasto_total`. Ordena de mayor a menor `gasto_total` y desempata por `cliente_id` ascendente.', '-- Reemplaza valores NULL de la suma con COALESCE
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido, COALESCE(SUM(p.total), 0) AS gasto_total FROM clientes c LEFT JOIN pedidos p ON c.cliente_id = p.cliente_id GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY gasto_total DESC, c.cliente_id ASC;', 55, 'Intermedio', TRUE, 38),
('e0000000-0000-0000-0000-000000000014', 'b0000000-0000-0000-0000-000000000007', 'Desglose completo de líneas de pedido', 'Audita las compras mostrando toda la información conectada: pedido, cliente, producto y categoría. Conecta `pedidos`, `clientes`, `detalle_pedidos`, `productos` y `categorias`, y muestra `pedido_id`, el nombre del cliente como `cliente_nombre`, `nombre_producto`, `nombre_categoria`, `cantidad` y `precio_unitario`. Ordena por `pedido_id ASC` y `nombre_producto ASC`, limitando a los primeros 10 registros.', '-- Conecta en cascada pedidos, clientes, detalle, productos y categorias
SELECT ', 'SELECT p.pedido_id, c.nombre AS cliente_nombre, pr.nombre_producto, cat.nombre_categoria, dp.cantidad, dp.precio_unitario FROM pedidos p INNER JOIN clientes c ON p.cliente_id = c.cliente_id INNER JOIN detalle_pedidos dp ON p.pedido_id = dp.pedido_id INNER JOIN productos pr ON dp.producto_id = pr.producto_id INNER JOIN categorias cat ON pr.categoria_id = cat.categoria_id ORDER BY p.pedido_id ASC, pr.nombre_producto ASC LIMIT 10;', 55, 'Intermedio', TRUE, 39),
('e0000000-0000-0000-0000-000000000039', 'b0000000-0000-0000-0000-000000000007', 'Historial de ventas por ciudad y categoría', 'Descubre cuánto dinero se ha vendido en cada ciudad por cada tipo de producto. Conecta las tablas necesarias para calcular la suma de ventas (`SUM(dp.cantidad * dp.precio_unitario)`) bajo el nombre `monto_vendido`, agrupando por la `ciudad` del cliente y el `nombre_categoria`. Ordena alfabéticamente por `ciudad` ascendente, luego de mayor a menor `monto_vendido` y, en caso de empate, por `nombre_categoria` ascendente.', '-- Conecta 5 tablas y calcula ventas por ciudad y categoria
SELECT ', 'SELECT c.ciudad, cat.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS monto_vendido FROM clientes c INNER JOIN pedidos p ON c.cliente_id = p.cliente_id INNER JOIN detalle_pedidos dp ON p.pedido_id = dp.pedido_id INNER JOIN productos pr ON dp.producto_id = pr.producto_id INNER JOIN categorias cat ON pr.categoria_id = cat.categoria_id GROUP BY c.ciudad, cat.nombre_categoria ORDER BY c.ciudad ASC, monto_vendido DESC, cat.nombre_categoria ASC;', 55, 'Intermedio', TRUE, 40),
('e0000000-0000-0000-0000-000000000040', 'b0000000-0000-0000-0000-000000000007', 'Conciliación de pedidos, facturación y pagos', 'Verifica el flujo completo de una compra: el pedido, su factura y su cobro. Conecta `pedidos` con `facturas` y `pagos`, mostrando `pedido_id`, `cliente_id`, el monto de la factura bajo el nombre `monto_factura`, el monto del pago bajo `monto_pago` y el `metodo_pago`. Ordena por `pedido_id` ascendente.', '-- Cruza pedidos con facturas y pagos
SELECT ', 'SELECT p.pedido_id, p.cliente_id, f.monto_total AS monto_factura, pg.monto AS monto_pago, pg.metodo_pago FROM pedidos p INNER JOIN facturas f ON p.pedido_id = f.pedido_id INNER JOIN pagos pg ON f.factura_id = pg.factura_id ORDER BY p.pedido_id ASC;', 55, 'Intermedio', TRUE, 41),
('e0000000-0000-0000-0000-000000000041', 'b0000000-0000-0000-0000-000000000007', 'Trazabilidad física de inventario por almacén', 'Consulta la disponibilidad física de inventario por almacén. Conecta `productos`, `inventario` y `almacenes`, mostrando `nombre_producto`, `nombre_almacen`, la `ciudad` del almacén y la `cantidad_disponible`, filtrando únicamente aquellos registros con más de 10 unidades. Ordena por nombre de producto y luego por almacén.', '-- Conecta productos, inventario y almacenes
SELECT ', 'SELECT pr.nombre_producto, a.nombre_almacen, a.ciudad, i.cantidad_disponible FROM productos pr INNER JOIN inventario i ON pr.producto_id = i.producto_id INNER JOIN almacenes a ON i.almacen_id = a.almacen_id WHERE i.cantidad_disponible > 10 ORDER BY pr.nombre_producto ASC, a.nombre_almacen ASC;', 55, 'Intermedio', TRUE, 42),
('e0000000-0000-0000-0000-000000000042', 'b0000000-0000-0000-0000-000000000008', 'Directorio operativo unificado (UNION)', 'Crea una lista unificada de todas las ciudades donde tenemos presencia, indicando si la presencia es de clientes o de almacenes. Combina con `UNION` la ciudad y la etiqueta `''cliente''` como `tipo_entidad` de la tabla `clientes`, con la ciudad y la etiqueta `''almacen''` como `tipo_entidad` de la tabla `almacenes`. Ordena por ciudad y por tipo de entidad.', '-- Combina ciudades de clientes y almacenes con UNION
SELECT ', 'SELECT ciudad, ''cliente'' AS tipo_entidad FROM clientes UNION SELECT ciudad, ''almacen'' AS tipo_entidad FROM almacenes ORDER BY ciudad ASC, tipo_entidad ASC;', 50, 'Intermedio', TRUE, 43),
('e0000000-0000-0000-0000-000000000054', 'b0000000-0000-0000-0000-000000000008', 'Ciudades con clientes y almacenes (INTERSECT)', 'Logística quiere identificar en qué ciudades coincidimos teniendo tanto clientes registrados como al menos un almacén físico. Usa el operador de conjuntos `INTERSECT` entre las ciudades de `clientes` y las ciudades de `almacenes`, ordenando el resultado alfabéticamente por `ciudad` ascendente.', '-- Intersección de conjuntos con INTERSECT
SELECT ', 'SELECT ciudad FROM clientes INTERSECT SELECT ciudad FROM almacenes ORDER BY ciudad ASC;', 50, 'Intermedio', TRUE, 44),
('e0000000-0000-0000-0000-000000000043', 'b0000000-0000-0000-0000-000000000008', 'Ciudades sin presencia de almacenes (EXCEPT)', 'Encuentra ciudades donde tengamos clientes pero todavía NO tengamos ningún almacén logístico. Usa el operador de diferencia `EXCEPT` para restar a las ciudades de `clientes` las ciudades de `almacenes`, ordenando la lista alfabéticamente.', '-- Diferencia de conjuntos con EXCEPT
SELECT ', 'SELECT ciudad FROM clientes EXCEPT SELECT ciudad FROM almacenes ORDER BY ciudad ASC;', 50, 'Intermedio', TRUE, 45),
('e0000000-0000-0000-0000-000000000044', 'b0000000-0000-0000-0000-000000000008', 'Matriz de cobertura Almacén-Categoría (CROSS JOIN)', 'Genera todas las combinaciones posibles entre cada almacén y cada categoría de productos. Usa un `CROSS JOIN` entre `almacenes` y `categorias`, mostrando `nombre_almacen` y `nombre_categoria`, ordenando por almacén y por categoría.', '-- Genera el producto cartesiano con CROSS JOIN
SELECT ', 'SELECT a.nombre_almacen, c.nombre_categoria FROM almacenes a CROSS JOIN categorias c ORDER BY a.nombre_almacen ASC, c.nombre_categoria ASC;', 50, 'Intermedio', TRUE, 46),
('e0000000-0000-0000-0000-000000000045', 'b0000000-0000-0000-0000-000000000008', 'Pares de productos de la misma categoría (SELF JOIN)', 'Genera sugerencias de productos emparejados dentro de la misma categoría. Cruza la tabla `productos` consigo misma (`p1` y `p2`) para emparejar artículos con la misma `categoria_id`, pidiendo que `p1.producto_id < p2.producto_id` para no emparejar un producto consigo mismo ni repetir la pareja al revés. Muestra `categoria_id`, los nombres como `producto_a` y `producto_b`, y los precios como `precio_a` y `precio_b`. Ordena por categoría y nombres.', '-- Auto-cruce de productos con condición de desigualdad
SELECT ', 'SELECT p1.categoria_id, p1.nombre_producto AS producto_a, p2.nombre_producto AS producto_b, p1.precio AS precio_a, p2.precio AS precio_b FROM productos p1 INNER JOIN productos p2 ON p1.categoria_id = p2.categoria_id AND p1.producto_id < p2.producto_id ORDER BY p1.categoria_id ASC, producto_a ASC, producto_b ASC;', 55, 'Intermedio', TRUE, 47),
('e0000000-0000-0000-0000-000000000015', 'c0000000-0000-0000-0000-000000000009', 'Productos sobre el promedio de precio', '¿Qué productos se venden por encima del precio promedio de toda la tienda? Muestra el `nombre_producto` y su `precio` para aquellos artículos cuyo precio sea mayor al promedio general de precios de la tabla `productos`. Ordena de mayor a menor precio y, en caso de empate, alfabéticamente por `nombre_producto`.', '-- Usa una subconsulta para comparar con el promedio global
SELECT ', 'SELECT nombre_producto, precio FROM productos WHERE precio > (SELECT AVG(precio) FROM productos) ORDER BY precio DESC, nombre_producto ASC;', 55, 'Avanzado', TRUE, 48),
('e0000000-0000-0000-0000-000000000046', 'c0000000-0000-0000-0000-000000000009', 'Clientes con pedidos de alto monto (subconsulta con IN)', 'Identifica a nuestros clientes VIP: aquellos que han hecho al menos un pedido importante (de 1000€ o más). Consulta la tabla `clientes` y muestra `cliente_id`, `nombre`, `apellido` y `email`, filtrando con una subconsulta usando el operador `IN` sobre la tabla `pedidos`. Ordena por `cliente_id` ascendente.', '-- Filtra clientes con una subconsulta en IN
SELECT ', 'SELECT cliente_id, nombre, apellido, email FROM clientes WHERE cliente_id IN (SELECT cliente_id FROM pedidos WHERE total >= 1000) ORDER BY cliente_id ASC;', 55, 'Avanzado', TRUE, 49),
('e0000000-0000-0000-0000-000000000047', 'c0000000-0000-0000-0000-000000000009', 'Comprobación de existencia eficiente (EXISTS)', 'Premia a los clientes activos que tengan al menos una compra completada. Muestra el `cliente_id`, `nombre` y `apellido` de aquellos clientes para los que exista al menos un pedido con `estado_pedido = ''completado''`, usando una subconsulta con `EXISTS`. Ordena por `cliente_id` ascendente.', '-- Subconsulta correlacionada con EXISTS
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c WHERE EXISTS (SELECT 1 FROM pedidos p WHERE p.cliente_id = c.cliente_id AND p.estado_pedido = ''completado'') ORDER BY c.cliente_id ASC;', 55, 'Avanzado', TRUE, 50),
('e0000000-0000-0000-0000-000000000055', 'c0000000-0000-0000-0000-000000000009', 'Clientes sin pedidos completados (NOT EXISTS)', 'Fidelización busca contactar a los clientes que aún no cuentan con ninguna compra completada (ya sea porque nunca compraron o porque sus órdenes fueron canceladas o están pendientes). Muestra `cliente_id`, `nombre` y `apellido` de `clientes` usando una subconsulta correlacionada con `NOT EXISTS` sobre `pedidos` filtrando por `estado_pedido = ''completado''`. Ordena por `cliente_id` ascendente.', '-- Subconsulta correlacionada negativa con NOT EXISTS
SELECT ', 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c WHERE NOT EXISTS (SELECT 1 FROM pedidos p WHERE p.cliente_id = c.cliente_id AND p.estado_pedido = ''completado'') ORDER BY c.cliente_id ASC;', 60, 'Avanzado', TRUE, 51),
('e0000000-0000-0000-0000-000000000016', 'c0000000-0000-0000-0000-000000000010', 'Segmentación de pedidos por monto', 'Clasifica los pedidos según su valor para organizar la entrega. Muestra el `pedido_id`, el `total` y una nueva columna llamada `segmento` que diga: si el total es de 1000€ o más asigna `''Alto Valor''`, si es de 300€ o más asigna `''Medio Valor''`, y para el resto `''Bajo Valor''`. Ordena de mayor a menor total y, en caso de empate, por `pedido_id` ascendente.', '-- Clasifica los pedidos en tres segmentos según su monto
SELECT ', 'SELECT pedido_id, total, CASE WHEN total >= 1000 THEN ''Alto Valor'' WHEN total >= 300 THEN ''Medio Valor'' ELSE ''Bajo Valor'' END AS segmento FROM pedidos ORDER BY total DESC, pedido_id ASC;', 55, 'Avanzado', TRUE, 52),
('e0000000-0000-0000-0000-000000000048', 'c0000000-0000-0000-0000-000000000010', 'Resumen de ventas por estado (agregación condicional)', 'Crea una tabla resumen que muestre cuánto dinero tiene cada cliente en compras completadas y cuánto en compras pendientes. Muestra el `cliente_id`, la suma de compras completadas bajo el nombre `ventas_completadas` (sumando el total cuando el estado sea `''completado''` y 0 si no) y la suma de compras pendientes bajo `ventas_pendientes` (sumando el total cuando sea `''pendiente''` y 0 si no). Agrupa y ordena por `cliente_id` ascendente.', '-- Agregación condicional con CASE dentro de SUM
SELECT ', 'SELECT cliente_id, SUM(CASE WHEN estado_pedido = ''completado'' THEN total ELSE 0 END) AS ventas_completadas, SUM(CASE WHEN estado_pedido = ''pendiente'' THEN total ELSE 0 END) AS ventas_pendientes FROM pedidos GROUP BY cliente_id ORDER BY cliente_id ASC;', 60, 'Avanzado', TRUE, 53),
('e0000000-0000-0000-0000-000000000056', 'c0000000-0000-0000-0000-000000000010', 'Conteo de productos por nivel de precio (COUNT + CASE)', 'Clasifica la composición del catálogo por categoría contando cuántos artículos de cada una pertenecen al rango premium (`precio >= 500`) y cuántos al rango estándar (`precio < 500`). Une `categorias` y `productos` con `LEFT JOIN`, muestra `nombre_categoria`, `productos_premium` y `productos_estandar` usando `COUNT(CASE WHEN ... THEN 1 END)`. Agrupa por categoría y ordena por `categoria_id` ascendente.', '-- Conteo condicional combinando COUNT y CASE
SELECT ', 'SELECT c.nombre_categoria, COUNT(CASE WHEN p.precio >= 500 THEN 1 END) AS productos_premium, COUNT(CASE WHEN p.precio < 500 THEN 1 END) AS productos_estandar FROM categorias c LEFT JOIN productos p ON c.categoria_id = p.categoria_id GROUP BY c.categoria_id, c.nombre_categoria ORDER BY c.categoria_id ASC;', 60, 'Avanzado', TRUE, 54),
('e0000000-0000-0000-0000-000000000017', 'c0000000-0000-0000-0000-000000000011', 'Facturación por categoría con CTE', 'Prepara un reporte ordenado de facturación por categoría usando una expresión `WITH` (CTE). Crea una tabla temporal llamada `ventas_por_categoria` que sume las ventas (`SUM(dp.cantidad * dp.precio_unitario)`) como `facturacion` agrupando por `nombre_categoria`. Luego, consulta esa tabla temporal para mostrar `nombre_categoria` y `facturacion` ordenados de mayor a menor facturación y, en caso de empate, alfabéticamente por `nombre_categoria`.', '-- Estructura la consulta analítica usando WITH ... AS
WITH ', 'WITH ventas_por_categoria AS (SELECT c.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS facturacion FROM categorias c INNER JOIN productos pr ON c.categoria_id = pr.categoria_id INNER JOIN detalle_pedidos dp ON pr.producto_id = dp.producto_id GROUP BY c.nombre_categoria) SELECT nombre_categoria, facturacion FROM ventas_por_categoria ORDER BY facturacion DESC, nombre_categoria ASC;', 60, 'Avanzado', TRUE, 55),
('e0000000-0000-0000-0000-000000000049', 'c0000000-0000-0000-0000-000000000011', 'CTEs múltiples encadenadas (análisis por etapas)', 'Construye un análisis por pasos usando dos CTEs encadenadas para encontrar a los clientes que gastan más que el promedio de todos los clientes. Primero crea `gasto_clientes` con el `cliente_id` y su gasto total (`SUM(total) AS total_gastado`). Luego crea `promedio_general` que calcule el promedio (`AVG(total_gastado) AS gasto_medio`) a partir de la primera. Finalmente, muestra `cliente_id` y `total_gastado` de aquellos clientes cuyo gasto supere el promedio general, ordenados de mayor a menor gasto y, en caso de empate, por `cliente_id` ascendente.', '-- Encadena dos CTEs separadas por coma
WITH ', 'WITH gasto_clientes AS (SELECT cliente_id, SUM(total) AS total_gastado FROM pedidos GROUP BY cliente_id), promedio_general AS (SELECT AVG(total_gastado) AS gasto_medio FROM gasto_clientes) SELECT g.cliente_id, g.total_gastado FROM gasto_clientes g CROSS JOIN promedio_general p WHERE g.total_gastado > p.gasto_medio ORDER BY g.total_gastado DESC, g.cliente_id ASC;', 60, 'Avanzado', TRUE, 56),
('e0000000-0000-0000-0000-000000000057', 'c0000000-0000-0000-0000-000000000011', 'Evolución mensual de ventas con CTE (TO_CHAR)', 'Dirección necesita una serie mensual de ingresos de pedidos completados. Define una CTE llamada `pedidos_mensuales` que transforme la fecha al formato año-mes con `TO_CHAR(fecha_pedido, ''YYYY-MM'') AS mes`, cuente los pedidos como `total_pedidos` y sume el total como `ingresos_mensuales` filtrando `estado_pedido = ''completado''`. Luego consulta esa CTE mostrando `mes`, `total_pedidos` e `ingresos_mensuales`, ordenados cronológicamente por `mes ASC`.', '-- Agrupación temporal por mes estructurada en una CTE
WITH ', 'WITH pedidos_mensuales AS (SELECT TO_CHAR(fecha_pedido, ''YYYY-MM'') AS mes, COUNT(*) AS total_pedidos, SUM(total) AS ingresos_mensuales FROM pedidos WHERE estado_pedido = ''completado'' GROUP BY TO_CHAR(fecha_pedido, ''YYYY-MM'')) SELECT mes, total_pedidos, ingresos_mensuales FROM pedidos_mensuales ORDER BY mes ASC;', 65, 'Avanzado', TRUE, 57),
('e0000000-0000-0000-0000-000000000058', 'c0000000-0000-0000-0000-000000000011', 'Categorías sobre el promedio de facturación (CTE + subconsulta)', 'Identifica qué categorías facturan por encima del promedio de todas las categorías. Crea una CTE llamada `facturacion_categoria` que sume las líneas de venta (`SUM(dp.cantidad * dp.precio_unitario) AS facturacion`) agrupando por `c.categoria_id` y `c.nombre_categoria`. En la consulta final, muestra `nombre_categoria` y `facturacion` filtrando aquellas cuyo valor supere `(SELECT AVG(facturacion) FROM facturacion_categoria)`. Ordena de mayor a menor `facturacion` y desempata por `nombre_categoria` ascendente.', '-- Reutiliza la misma CTE en una subconsulta escalar
WITH ', 'WITH facturacion_categoria AS (SELECT c.categoria_id, c.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS facturacion FROM categorias c INNER JOIN productos pr ON c.categoria_id = pr.categoria_id INNER JOIN detalle_pedidos dp ON pr.producto_id = dp.producto_id GROUP BY c.categoria_id, c.nombre_categoria) SELECT nombre_categoria, facturacion FROM facturacion_categoria WHERE facturacion > (SELECT AVG(facturacion) FROM facturacion_categoria) ORDER BY facturacion DESC, nombre_categoria ASC;', 65, 'Avanzado', TRUE, 58),
('e0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000012', 'Ranking de productos por precio (ROW_NUMBER)', 'Crea una lista clasificada de productos del más caro al más económico. Muestra `producto_id`, `nombre_producto`, `precio` y una columna llamada `ranking` con la posición consecutiva (1, 2, 3...) de cada producto usando `ROW_NUMBER()` ordenado por precio descendente (desempatando por `producto_id` ascendente), y ordena el resultado final por `ranking` ascendente.', '-- Emplea ROW_NUMBER() OVER (...)
SELECT ', 'SELECT producto_id, nombre_producto, precio, ROW_NUMBER() OVER (ORDER BY precio DESC, producto_id ASC) AS ranking FROM productos ORDER BY ranking ASC;', 55, 'Avanzado', TRUE, 59),
('e0000000-0000-0000-0000-000000000018', 'c0000000-0000-0000-0000-000000000012', 'Ranking relativo por categoría (DENSE_RANK)', 'Clasifica los productos dentro de cada categoría del más caro al más barato. Muestra `categoria_id`, `nombre_producto`, `precio` y una columna con el puesto que ocupa llamada `ranking_categoria` usando `DENSE_RANK()`, dividiendo por categoría y ordenando de mayor a menor precio. Ordena por `categoria_id ASC`, `ranking_categoria ASC` y `nombre_producto ASC`.', '-- Usa DENSE_RANK() particionado por categoria_id
SELECT ', 'SELECT categoria_id, nombre_producto, precio, DENSE_RANK() OVER (PARTITION BY categoria_id ORDER BY precio DESC) AS ranking_categoria FROM productos ORDER BY categoria_id ASC, ranking_categoria ASC, nombre_producto ASC;', 65, 'Avanzado', TRUE, 60),
('e0000000-0000-0000-0000-000000000059', 'c0000000-0000-0000-0000-000000000012', 'Producto más caro por categoría (CTE + ROW_NUMBER)', 'Encuentra el artículo líder en precio dentro de cada categoría. Crea una CTE `ranking_productos` que proyecte `categoria_id`, `nombre_producto`, `precio` y `ROW_NUMBER() OVER (PARTITION BY categoria_id ORDER BY precio DESC, producto_id ASC) AS posicion` desde `productos`. Luego selecciona `categoria_id`, `nombre_producto` y `precio` filtrando únicamente `WHERE posicion = 1` y ordenando por `categoria_id ASC`.', '-- Patrón de artículo líder por categoría combinando CTE y ROW_NUMBER()
WITH ', 'WITH ranking_productos AS (SELECT categoria_id, nombre_producto, precio, ROW_NUMBER() OVER (PARTITION BY categoria_id ORDER BY precio DESC, producto_id ASC) AS posicion FROM productos) SELECT categoria_id, nombre_producto, precio FROM ranking_productos WHERE posicion = 1 ORDER BY categoria_id ASC;', 70, 'Avanzado', TRUE, 61),
('e0000000-0000-0000-0000-000000000060', 'c0000000-0000-0000-0000-000000000012', 'Ingresos acumulados progresivos (SUM OVER)', 'Calcula la curva acumulada de facturación pedido a pedido. Para los pedidos con `estado_pedido = ''completado''`, muestra `pedido_id`, `fecha_pedido`, `total` y una columna llamada `ingresos_acumulados` usando `SUM(total) OVER (ORDER BY fecha_pedido ASC, pedido_id ASC)`. Ordena la salida por `fecha_pedido ASC` y `pedido_id ASC`.', '-- Total acumulado progresivo con SUM() OVER
SELECT ', 'SELECT pedido_id, fecha_pedido, total, SUM(total) OVER (ORDER BY fecha_pedido ASC, pedido_id ASC) AS ingresos_acumulados FROM pedidos WHERE estado_pedido = ''completado'' ORDER BY fecha_pedido ASC, pedido_id ASC;', 70, 'Avanzado', TRUE, 62),
('e0000000-0000-0000-0000-000000000050', 'c0000000-0000-0000-0000-000000000012', 'Análisis de intervalo temporal entre pedidos (LAG)', 'Analiza cuánto tiempo pasa entre una compra y otra para cada cliente. Muestra el `pedido_id`, `cliente_id`, la `fecha_pedido` y el valor de la fecha del pedido inmediatamente anterior bajo el nombre `fecha_pedido_anterior`, usando la función de ventana `LAG(fecha_pedido)` dividiendo por cliente y ordenando cronológicamente (`fecha_pedido ASC, pedido_id ASC`). Ordena los resultados finales por `cliente_id ASC`, `fecha_pedido ASC` y `pedido_id ASC`.', '-- Emplea LAG() OVER (PARTITION BY ... ORDER BY ...)
SELECT ', 'SELECT pedido_id, cliente_id, fecha_pedido, LAG(fecha_pedido) OVER (PARTITION BY cliente_id ORDER BY fecha_pedido ASC, pedido_id ASC) AS fecha_pedido_anterior FROM pedidos ORDER BY cliente_id ASC, fecha_pedido ASC, pedido_id ASC;', 60, 'Avanzado', TRUE, 63),
('e0000000-0000-0000-0000-000000000061', 'd0000000-0000-0000-0000-000000000013', 'Alta de nueva categoría en catálogo (INSERT VALUES)', 'La tienda abrirá una línea especializada en sonido. Inserta una nueva fila en la tabla `categorias` especificando únicamente las columnas `nombre_categoria` con el valor `''Audio Profesional''` y `descripcion` con el valor `''Micrófonos de estudio, interfaces y monitores de audio''`, dejando que la clave primaria `categoria_id` se asigne automáticamente.', '-- Inserta la nueva categoría especificando sus dos columnas de texto
UPDATE ', 'UPDATE proveedores SET telefono = ''+886-2-999888'' WHERE proveedor_id = 2;', 50, 'Intermedio', TRUE, 69),
('e0000000-0000-0000-0000-000000000066', 'd0000000-0000-0000-0000-000000000014', 'Ajuste de precios por categoría con confirmación (UPDATE RETURNING)', 'Aplica un incremento del 10% al precio de todos los productos de la categoría `4` (`Almacenamiento`). Actualiza la tabla `productos` asignando `precio = ROUND(precio * 1.10, 2)` donde `categoria_id = 4`, y utiliza `RETURNING` para mostrar `producto_id`, `nombre_producto` y el nuevo `precio`.', '-- Incrementa el precio un 10% con ROUND y muestra los cambios con RETURNING
UPDATE ', 'UPDATE productos SET precio = ROUND(precio * 1.10, 2) WHERE categoria_id = 4 RETURNING producto_id, nombre_producto, precio;', 60, 'Intermedio', FALSE, 70),
('e0000000-0000-0000-0000-000000000067', 'd0000000-0000-0000-0000-000000000014', 'Actualización cruzada de inventario por ciudad (UPDATE ... FROM)', 'Suma `5` unidades de reserva (`cantidad_disponible = cantidad_disponible + 5`) en la tabla `inventario` únicamente para los registros pertenecientes a almacenes ubicados en la ciudad de `''Bilbao''`. Utiliza la sintaxis `UPDATE inventario i SET ... FROM almacenes a WHERE i.almacen_id = a.almacen_id AND a.ciudad = ''Bilbao''`.', '-- Usa UPDATE ... FROM para actualizar inventario filtrando por una columna de almacenes
UPDATE ', 'UPDATE inventario i SET cantidad_disponible = i.cantidad_disponible + 5 FROM almacenes a WHERE i.almacen_id = a.almacen_id AND a.ciudad = ''Bilbao'';', 70, 'Intermedio', TRUE, 71),
('e0000000-0000-0000-0000-000000000068', 'd0000000-0000-0000-0000-000000000014', 'Depuración segura de líneas de pedido cancelado (DELETE WHERE)', 'El pedido con `pedido_id = 105` fue cancelado definitivamente y Finanzas solicita limpiar sus líneas de detalle antes de archivar. Elimina de la tabla `detalle_pedidos` únicamente el registro que pertenece a `pedido_id = 105`.', '-- Elimina exclusivamente las líneas del pedido 105 en detalle_pedidos
DELETE FROM ', 'DELETE FROM detalle_pedidos WHERE pedido_id = 105;', 60, 'Intermedio', TRUE, 72),
('e0000000-0000-0000-0000-000000000069', 'd0000000-0000-0000-0000-000000000015', 'Diseño de tabla de cupones promocionales (CREATE TABLE)', 'Diseña una nueva tabla llamada `cupones_descuento` para gestionar campañas promocionales con exactamente estas 4 columnas en orden:
1. `cupon_id` de tipo `SERIAL PRIMARY KEY`
2. `codigo` de tipo `VARCHAR(25) NOT NULL`
3. `descuento_pct` de tipo `NUMERIC(5, 2) NOT NULL`
4. `fecha_expiracion` de tipo `DATE NOT NULL`', '-- Define la tabla cupones_descuento con sus 4 columnas y tipos exactos
CREATE TABLE ', 'CREATE TABLE cupones_descuento (cupon_id SERIAL PRIMARY KEY, codigo VARCHAR(25) NOT NULL, descuento_pct NUMERIC(5, 2) NOT NULL, fecha_expiracion DATE NOT NULL);', 60, 'Intermedio', TRUE, 73),
('e0000000-0000-0000-0000-000000000070', 'd0000000-0000-0000-0000-000000000015', 'Tabla de reseñas con reglas de integridad (CHECK & FOREIGN KEY)', 'Crea la tabla `resenas_productos` para almacenar valoraciones verificadas con estas 5 columnas en orden:
1. `resena_id` de tipo `SERIAL PRIMARY KEY`
2. `producto_id` de tipo `INT NOT NULL REFERENCES productos(producto_id)`
3. `cliente_id` de tipo `INT NOT NULL REFERENCES clientes(cliente_id)`
4. `calificacion` de tipo `INT NOT NULL CHECK (calificacion BETWEEN 1 AND 5)`
5. `comentario` de tipo `TEXT`', '-- Crea la tabla resenas_productos con claves foráneas y restricción CHECK
CREATE TABLE ', 'CREATE TABLE resenas_productos (resena_id SERIAL PRIMARY KEY, producto_id INT NOT NULL REFERENCES productos(producto_id), cliente_id INT NOT NULL REFERENCES clientes(cliente_id), calificacion INT NOT NULL CHECK (calificacion BETWEEN 1 AND 5), comentario TEXT);', 70, 'Intermedio', TRUE, 74),
('e0000000-0000-0000-0000-000000000071', 'd0000000-0000-0000-0000-000000000015', 'Evolución de esquema en almacenes (ALTER TABLE ADD COLUMN)', 'Operaciones necesita identificar qué centros logísticos cuentan con cámara refrigerada. Modifica la tabla `almacenes` con `ALTER TABLE` para agregar una nueva columna llamada `refrigerado` de tipo `BOOLEAN NOT NULL DEFAULT FALSE`.', '-- Agrega la columna refrigerado con su valor por defecto a la tabla almacenes
ALTER TABLE ', 'ALTER TABLE almacenes ADD COLUMN refrigerado BOOLEAN NOT NULL DEFAULT FALSE;', 65, 'Intermedio', TRUE, 75),
('e0000000-0000-0000-0000-000000000072', 'd0000000-0000-0000-0000-000000000015', 'Retiro controlado de tabla obsoleta (DROP TABLE IF EXISTS CASCADE)', 'En el esquema de trabajo existe una tabla heredada llamada `auditoria_obsoleta` (junto con una vista dependiente) que debe retirarse limpiamente. Ejecuta la instrucción para eliminar la tabla `auditoria_obsoleta` utilizando `IF EXISTS` y `CASCADE` para remover también sus objetos dependientes.', '-- Elimina la tabla auditoria_obsoleta de forma segura con IF EXISTS y CASCADE
DROP TABLE ', 'DROP TABLE IF EXISTS auditoria_obsoleta CASCADE;', 60, 'Intermedio', TRUE, 76),
('e0000000-0000-0000-0000-000000000073', 'd0000000-0000-0000-0000-000000000016', 'Índice B-Tree para búsqueda por ciudad (CREATE INDEX)', 'Las consultas de marketing filtran constantemente la tabla `clientes` por la columna `ciudad`, provocando escaneos secuenciales (`Seq Scan`). Crea un índice B-Tree estándar llamado `idx_clientes_ciudad` sobre la tabla `clientes` indexando la columna `(ciudad)`.', '-- Crea el índice idx_clientes_ciudad sobre la tabla clientes
CREATE INDEX ', 'CREATE INDEX idx_clientes_ciudad ON clientes (ciudad);', 70, 'Avanzado', TRUE, 77),
('e0000000-0000-0000-0000-000000000074', 'd0000000-0000-0000-0000-000000000016', 'Índice único compuesto de facturación (CREATE UNIQUE INDEX)', 'Para evitar que se registre por error más de un pago con el mismo método para la misma factura y acelerar las conciliaciones, crea un índice **único** y **compuesto** llamado `idx_pagos_factura_metodo_unico` sobre la tabla `pagos` con las columnas `(factura_id, metodo_pago)` en ese orden.', '-- Crea un índice único compuesto sobre factura_id y metodo_pago
CREATE UNIQUE INDEX ', 'CREATE UNIQUE INDEX idx_pagos_factura_metodo_unico ON pagos (factura_id, metodo_pago);', 75, 'Avanzado', TRUE, 78),
('e0000000-0000-0000-0000-000000000075', 'd0000000-0000-0000-0000-000000000016', 'Índice parcial de pedidos pendientes (partial index WHERE)', 'En producción el 95% de los pedidos históricos están `''completado''`, pero el panel operativo consulta miles de veces por minuto solo los pedidos con `estado_pedido = ''pendiente''` ordenados por `fecha_pedido`. Crea un **índice parcial** llamado `idx_pedidos_pendientes_fecha` sobre `pedidos (fecha_pedido)` que indexe únicamente las filas `WHERE estado_pedido = ''pendiente''`.', '-- Crea un índice parcial filtrando con WHERE al final de CREATE INDEX
CREATE INDEX ', 'CREATE INDEX idx_pedidos_pendientes_fecha ON pedidos (fecha_pedido) WHERE estado_pedido = ''pendiente'';', 85, 'Avanzado', TRUE, 79),
('e0000000-0000-0000-0000-000000000076', 'd0000000-0000-0000-0000-000000000016', 'Eliminación de índice redundante (DROP INDEX IF EXISTS)', 'Durante una auditoría de rendimiento en la tabla `clientes` se detectó un índice duplicado y sin uso llamado `idx_clientes_pais_antiguo` que ralentiza las inserciones. Elimina dicho índice del catálogo de forma segura utilizando `DROP INDEX IF EXISTS`.', '-- Elimina el índice idx_clientes_pais_antiguo con IF EXISTS
DROP INDEX ', 'DROP INDEX IF EXISTS idx_clientes_pais_antiguo;', 70, 'Avanzado', TRUE, 80)
