INSERT INTO public.learning_paths (id, title, description, difficulty, estimated_hours, badge_reward, sort_order) VALUES
('sql-foundations', 'Fundamentos de SQL', 'Aprende a consultar bases de datos desde cero. Proyecciones con SELECT, cálculos derivados, filtrado con WHERE y fechas, ordenamiento y agregaciones globales.', 'Principiante', 7, 'Primera Consulta', 1),
('relational-sql', 'SQL Relacional', 'Domina el cruce de tablas relacionales. Claves foráneas, uniones con INNER JOIN, detección de ausencias con LEFT JOIN y COALESCE, consultas multi-tabla y operaciones de conjunto.', 'Intermedio', 9, 'Maestro de Relaciones', 2),
('advanced-queries', 'Consultas Avanzadas', 'Eleva tu nivel con subconsultas correlacionadas (EXISTS/NOT EXISTS), expresiones condicionales CASE, consultas temporales con WITH (CTEs) y funciones analíticas de ventana.', 'Avanzado', 14, 'Maestro de Ventanas', 3),
('data-manipulation-ddl', 'Ingeniería y Manipulación de Datos', 'Domina la escritura transaccional, el diseño de esquemas relacionales y la optimización física con INSERT, UPDATE, DELETE, RETURNING, CREATE/ALTER/DROP TABLE e índices B-Tree compuestos y parciales.', 'Avanzado', 12, 'Arquitecto Relacional', 4)
INSERT INTO public.modules (id, path_id, module_number, title, description) VALUES
('a0000000-0000-0000-0000-000000000001', 'sql-foundations', 1, 'SELECT y Proyecciones de Datos', 'Aprende a solicitar columnas específicas y utilizar alias y cálculos aritméticos limpios.'),
('a0000000-0000-0000-0000-000000000002', 'sql-foundations', 2, 'Filtrado con WHERE y Operadores Lógicos', 'Aplica filtros condicionales exactos mediante operadores de comparación, patrones, fechas y rangos con BETWEEN.'),
('a0000000-0000-0000-0000-000000000003', 'sql-foundations', 3, 'Ordenamiento y Paginación', 'Ordena resultados con ORDER BY (ASC/DESC) y limita registros devueltos con LIMIT y OFFSET.'),
('a0000000-0000-0000-0000-000000000004', 'sql-foundations', 4, 'Agregación y Agrupamiento', 'Resume datos de lo global a lo agrupado con COUNT, SUM, AVG, WHERE previo y filtrado de grupos con HAVING.'),
('b0000000-0000-0000-0000-000000000005', 'relational-sql', 5, 'Uniones Fundamentales (INNER JOIN)', 'Cruza tablas relacionales mediante claves foráneas antes de dar el salto a agregaciones cruzadas.'),
('b0000000-0000-0000-0000-000000000006', 'relational-sql', 6, 'Detección de Ausencias (LEFT JOIN y NULL)', 'Identifica registros huérfanos o entidades sin actividad asociada mediante LEFT JOIN, IS NULL y COALESCE.'),
('b0000000-0000-0000-0000-000000000007', 'relational-sql', 7, 'Consultas Multi-Tabla en Cascada', 'Conecta 3 o más tablas para análisis integral del negocio en cascada relacional.'),
('b0000000-0000-0000-0000-000000000008', 'relational-sql', 8, 'Operaciones de Conjunto y Uniones Especiales', 'Combina consultas mediante UNION, INTERSECT, EXCEPT, CROSS JOIN y auto-uniones con SELF JOIN.'),
('c0000000-0000-0000-0000-000000000009', 'advanced-queries', 9, 'Subconsultas Analíticas', 'Integra subconsultas escalares, listas IN y pruebas de existencia (EXISTS / NOT EXISTS) en WHERE.'),
('c0000000-0000-0000-0000-000000000010', 'advanced-queries', 10, 'Expresiones Condicionales (CASE)', 'Transforma, categoriza y pivota métricas y conteos al vuelo con lógica condicional CASE.'),
('c0000000-0000-0000-0000-000000000011', 'advanced-queries', 11, 'Consultas Temporales con WITH (CTEs)', 'Estructura análisis temporales, comparativas entre grupos y flujos por etapas con la cláusula WITH.'),
('c0000000-0000-0000-0000-000000000012', 'advanced-queries', 12, 'Funciones Analíticas de Ventana', 'Aplica clasificaciones, máximos por grupo, acumulados progresivos y análisis temporal (ROW_NUMBER, DENSE_RANK, SUM OVER, LAG).'),
('d0000000-0000-0000-0000-000000000013', 'data-manipulation-ddl', 13, 'Inserción de Registros (INSERT)', 'Registra tuplas individuales, lotes multi-fila, proyecciones inmediatas con RETURNING y abastecimiento entre tablas con INSERT INTO ... SELECT.'),
('d0000000-0000-0000-0000-000000000014', 'data-manipulation-ddl', 14, 'Actualización y Eliminación Segura (UPDATE y DELETE)', 'Modifica y depura datos con precisión quirúrgica usando UPDATE ... WHERE, recálculos con RETURNING, cruces UPDATE ... FROM y DELETE seguro.'),
('d0000000-0000-0000-0000-000000000015', 'data-manipulation-ddl', 15, 'Creación y Evolución de Tablas (CREATE, ALTER y DROP)', 'Diseña tablas con claves primarias, foráneas y restricciones CHECK, evoluciona columnas con ALTER TABLE y retira estructuras con DROP TABLE CASCADE.'),
('d0000000-0000-0000-0000-000000000016', 'data-manipulation-ddl', 16, 'Índices y Optimización Estructural (CREATE INDEX)', 'Acelera consultas creando índices B-Tree simples, índices únicos compuestos, índices parciales filtrados con WHERE y limpieza con DROP INDEX.')
INSERT INTO public.exercises (id, module_id, title, prompt, initial_code, solution_query, xp_reward, difficulty, check_order, sort_order) VALUES
('e0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'Catálogo básico de productos', 'Imagina que necesitas armar un catálogo sencillo para la tienda. Muestra únicamente el nombre de cada producto (`nombre_producto`) y su precio (`precio`) desde la tabla `productos`.', '-- Escribe tu consulta aquí
INSERT INTO ', 'INSERT INTO categorias (nombre_categoria, descripcion) VALUES (''Audio Profesional'', ''Micrófonos de estudio, interfaces y monitores de audio'');', 50, 'Intermedio', TRUE, 64),
('e0000000-0000-0000-0000-000000000062', 'd0000000-0000-0000-0000-000000000013', 'Registro múltiple de almacenes regionales (INSERT Multi-Fila)', 'Expande la red logística registrando dos centros en una sola sentencia sobre la tabla `almacenes` (columnas `nombre_almacen`, `ciudad`, `capacidad_m2`): el primero con `''Centro Logístico Sur''`, `''Sevilla''` y `3200`; y el segundo con `''Hub Atlántico''`, `''Vigo''` y `2400`.', '-- Inserta ambos almacenes en una única instrucción INSERT
INSERT INTO ', 'INSERT INTO almacenes (nombre_almacen, ciudad, capacidad_m2) VALUES (''Centro Logístico Sur'', ''Sevilla'', 3200), (''Hub Atlántico'', ''Vigo'', 2400);', 55, 'Intermedio', TRUE, 65),
('e0000000-0000-0000-0000-000000000063', 'd0000000-0000-0000-0000-000000000013', 'Alta de producto con confirmación inmediata (INSERT RETURNING)', 'Registra un nuevo artículo en `productos` con `categoria_id = 3`, `proveedor_id = 5`, `nombre_producto = ''Webcam 4K Studio''`, `precio = 125.00` y `stock = 30`. En la misma sentencia, utiliza la cláusula `RETURNING` para devolver únicamente `producto_id`, `nombre_producto`, `precio` y `stock`.', '-- Inserta el producto y devuelve las 4 columnas solicitadas con RETURNING
INSERT INTO ', 'INSERT INTO productos (categoria_id, proveedor_id, nombre_producto, precio, stock) VALUES (3, 5, ''Webcam 4K Studio'', 125.00, 30) RETURNING producto_id, nombre_producto, precio, stock;', 60, 'Intermedio', TRUE, 66),
('e0000000-0000-0000-0000-000000000064', 'd0000000-0000-0000-0000-000000000013', 'Abastecimiento de inventario desde catálogo (INSERT INTO ... SELECT)', 'El almacén con `almacen_id = 3` va a incorporar un lote inicial de `12` unidades para los artículos de la categoría `5` (`Mobiliario Ergonómico`). Como el artículo con `producto_id = 15` ya tiene existencias registradas en ese almacén, debes excluirlo para no duplicar la clave primaria compuesta. Inserta en `inventario` las columnas `(almacen_id, producto_id, cantidad_disponible)` usando `INSERT INTO ... SELECT` para proyectar la constante `3`, el `producto_id` y la constante `12` desde la tabla `productos` filtrando `categoria_id = 5` y `producto_id <> 15`.', '-- Usa INSERT INTO ... SELECT para poblar inventario a partir de productos
INSERT INTO ', 'INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) SELECT 3, producto_id, 12 FROM productos WHERE categoria_id = 5 AND producto_id <> 15;', 65, 'Intermedio', TRUE, 67),
('e0000000-0000-0000-0000-000000000080', 'd0000000-0000-0000-0000-000000000013', 'Reposición inteligente de stock (UPSERT con ON CONFLICT)', 'Llegó al almacén `3` una reposición de `20` unidades del artículo `15` (`almacen_id = 3, producto_id = 15, cantidad_disponible = 20`). Como ese par ya existe en la tabla `inventario`, un `INSERT` convencional fallaría por colisión de clave primaria compuesta. Ejecuta un `INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) VALUES (3, 15, 20)` utilizando `ON CONFLICT (almacen_id, producto_id) DO UPDATE` para sumar la nueva cantidad al stock existente (`inventario.cantidad_disponible + EXCLUDED.cantidad_disponible`) y proyecta el resultado con `RETURNING almacen_id, producto_id, cantidad_disponible`.', '-- Inserta o suma stock si la clave compuesta ya existe con ON CONFLICT
INSERT INTO ', 'INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) VALUES (3, 15, 20) ON CONFLICT (almacen_id, producto_id) DO UPDATE SET cantidad_disponible = inventario.cantidad_disponible + EXCLUDED.cantidad_disponible RETURNING almacen_id, producto_id, cantidad_disponible;', 55, 'Intermedio', TRUE, 68),
('e0000000-0000-0000-0000-000000000065', 'd0000000-0000-0000-0000-000000000014', 'Actualización de contacto de proveedor (UPDATE WHERE)', 'El proveedor con `proveedor_id = 2` (`Silicon Logistics`) actualizó su línea telefónica internacional. Modifica la tabla `proveedores` asignando `telefono = ''+886-2-999888''` exclusivamente para el registro con `proveedor_id = 2`.', '-- Actualiza el teléfono filtrando por clave primaria
INSERT INTO public.exercise_hints (exercise_id, hint_order, content, xp_penalty_percent) VALUES
('e0000000-0000-0000-0000-000000000001', 1, 'Identifica la tabla que guarda el catálogo de artículos y qué dos columnas contienen el nombre y el precio.', 15),
('e0000000-0000-0000-0000-000000000001', 2, 'Usa SELECT seguido de las columnas separadas por coma y FROM para indicar la tabla.', 20),
('e0000000-0000-0000-0000-000000000001', 3, 'SELECT ???, ??? FROM productos;', 25),
('e0000000-0000-0000-0000-000000000008', 1, 'Puedes calcular valores nuevos al vuelo multiplicando la columna numérica por 1.21.', 15),
('e0000000-0000-0000-0000-000000000008', 2, 'Combina la multiplicación con ROUND(..., 2) para dejar dos decimales y AS para nombrar la columna.', 20),
('e0000000-0000-0000-0000-000000000008', 3, 'SELECT ???, ???, ROUND(??? * 1.21, 2) AS precio_con_iva FROM productos;', 25),
('e0000000-0000-0000-0000-000000000019', 1, 'Necesitas unir dos columnas de texto intercalando un espacio en blanco entre ellas.', 15),
('e0000000-0000-0000-0000-000000000019', 2, 'Utiliza el operador || junto con un espacio literal '' '' y asigna el alias cliente_completo con AS.', 20),
('e0000000-0000-0000-0000-000000000019', 3, 'SELECT ??? || '' '' || ??? AS cliente_completo, ??? FROM clientes;', 25),
('e0000000-0000-0000-0000-000000000020', 1, 'Para evitar que una ciudad aparezca varias veces, debes eliminar filas repetidas en el resultado.', 15),
('e0000000-0000-0000-0000-000000000020', 2, 'Coloca la palabra clave DISTINCT inmediatamente después de SELECT antes de nombrar la columna.', 20),
('e0000000-0000-0000-0000-000000000020', 3, 'SELECT DISTINCT ??? FROM clientes;', 25),
('e0000000-0000-0000-0000-000000000002', 1, 'Debes mostrar tres columnas del catálogo y conservar solo los artículos cuyo precio supera el umbral.', 15),
('e0000000-0000-0000-0000-000000000002', 2, 'Añade la cláusula WHERE después de FROM y compara la columna numérica con el operador >.', 20),
('e0000000-0000-0000-0000-000000000002', 3, 'SELECT ???, ???, ??? FROM productos WHERE ??? > 500;', 25),
('e0000000-0000-0000-0000-000000000009', 1, 'Necesitas filtrar artículos que caigan dentro de un rango numérico incluyendo ambos extremos.', 15),
('e0000000-0000-0000-0000-000000000009', 2, 'Usa WHERE con el operador BETWEEN conectando el límite inferior y superior con AND.', 20),
('e0000000-0000-0000-0000-000000000009', 3, 'SELECT ???, ??? FROM productos WHERE ??? BETWEEN 100 AND 800;', 25),
('e0000000-0000-0000-0000-000000000021', 1, 'Debes buscar coincidencias parciales al final de la cadena de correo electrónico.', 15),
('e0000000-0000-0000-0000-000000000021', 2, 'Usa WHERE con LIKE y el comodín % al principio del patrón entre comillas simples.', 20),
('e0000000-0000-0000-0000-000000000021', 3, 'SELECT ???, ???, ??? FROM clientes WHERE ??? LIKE ''%@email.com'';', 25),
('e0000000-0000-0000-0000-000000000022', 1, 'En lugar de escribir varios OR seguidos, conviene comprobar pertenencia a una lista cerrada de valores.', 15),
('e0000000-0000-0000-0000-000000000022', 2, 'Emplea WHERE con el operador IN (...) encerrando cada ciudad entre comillas simples.', 20),
('e0000000-0000-0000-0000-000000000022', 3, 'SELECT ???, ???, ???, ??? FROM clientes WHERE ??? IN (''Madrid'', ''Barcelona'', ''Valencia'');', 25),
('e0000000-0000-0000-0000-000000000023', 1, 'Un artículo cumple si se encuentra en cualquiera de los dos extremos de existencias (bajo o exceso).', 15),
('e0000000-0000-0000-0000-000000000023', 2, 'Combina las dos comparaciones (<= 15 y >= 75) en WHERE usando el operador lógico OR.', 20),
('e0000000-0000-0000-0000-000000000023', 3, 'SELECT ???, ???, ??? FROM productos WHERE ??? <= 15 OR ??? >= 75;', 25),
('e0000000-0000-0000-0000-000000000024', 1, 'Deben cumplirse dos condiciones a la vez: un monto mínimo y un estado distinto a ''pagada''.', 15),
('e0000000-0000-0000-0000-000000000024', 2, 'Une en WHERE la comparación >= 400 con el operador de desigualdad <> (o !=) usando AND.', 20),
('e0000000-0000-0000-0000-000000000024', 3, 'SELECT ???, ???, ??? FROM facturas WHERE ??? >= 400 AND ??? <> ''pagada'';', 25),
('e0000000-0000-0000-0000-000000000078', 1, 'En SQL el operador AND se evalúa antes que OR; si no usas paréntesis, el filtro de precio solo afectará a la segunda categoría.', 15),
('e0000000-0000-0000-0000-000000000078', 2, 'Encierra (categoria_id = 1 OR categoria_id = 2) entre paréntesis, combínalo con AND precio < 1000 y ordena por producto_id ASC.', 20),
('e0000000-0000-0000-0000-000000000078', 3, 'SELECT producto_id, categoria_id, nombre_producto, precio, stock FROM productos WHERE (??? = 1 OR ??? = 2) AND precio < 1000 ORDER BY producto_id ASC;', 25),
('e0000000-0000-0000-0000-000000000077', 1, 'En SQL un valor ausente (NULL) no es igual a nada, ni siquiera a otro NULL; por eso no puedes usar el signo =.', 15),
('e0000000-0000-0000-0000-000000000077', 2, 'Filtra en la cláusula WHERE usando el predicado IS NULL sobre la columna de contacto telefónico.', 20),
('e0000000-0000-0000-0000-000000000077', 3, 'SELECT ???, ???, ??? FROM proveedores WHERE ??? IS NULL;', 25),
('e0000000-0000-0000-0000-000000000051', 1, 'Las fechas en formato estándar se comparan como texto delimitado entre comillas simples (''AAAA-MM-DD'') dentro de WHERE.', 15),
('e0000000-0000-0000-0000-000000000051', 2, 'Usa BETWEEN ''2024-02-01'' AND ''2024-02-29'' sobre fecha_pedido y ordena con fecha_pedido ASC, pedido_id ASC.', 20),
('e0000000-0000-0000-0000-000000000051', 3, 'SELECT ???, ???, ???, ??? FROM pedidos WHERE ??? BETWEEN ''2024-02-01'' AND ''2024-02-29'' ORDER BY fecha_pedido ASC, pedido_id ASC;', 25),
('e0000000-0000-0000-0000-000000000003', 1, 'Primero filtra por el país solicitado y luego ordena las filas resultantes de forma alfabética con desempate único.', 15),
('e0000000-0000-0000-0000-000000000003', 2, 'Aplica WHERE pais = ''España'' y añade ORDER BY apellido ASC, cliente_id ASC al final.', 20),
('e0000000-0000-0000-0000-000000000003', 3, 'SELECT ???, ???, ??? FROM clientes WHERE ??? = ''España'' ORDER BY ??? ASC, cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000010', 1, 'Para hallar los valores más pequeños primero ordena de menor a mayor con desempate único y luego recorta el resultado.', 15),
('e0000000-0000-0000-0000-000000000010', 2, 'Usa ORDER BY stock ASC, producto_id ASC seguido de LIMIT 5.', 20),
('e0000000-0000-0000-0000-000000000010', 3, 'SELECT ???, ??? FROM productos ORDER BY ??? ASC, producto_id ASC LIMIT 5;', 25),
('e0000000-0000-0000-0000-000000000025', 1, 'Primero agrupa visualmente ordenando por categoría y luego desempata los precios de mayor a menor.', 15),
('e0000000-0000-0000-0000-000000000025', 2, 'Especifica dos criterios en ORDER BY separados por coma: primero ASC y el segundo DESC.', 20),
('e0000000-0000-0000-0000-000000000025', 3, 'SELECT ???, ???, ???, ??? FROM productos ORDER BY ??? ASC, ??? DESC;', 25),
('e0000000-0000-0000-0000-000000000026', 1, 'Para mostrar la segunda página de 5 elementos debes ordenar primero de forma estable, saltar 5 filas y tomar 5.', 15),
('e0000000-0000-0000-0000-000000000026', 2, 'Combina ORDER BY cliente_id ASC con LIMIT 5 y OFFSET 5 al final de la consulta.', 20),
('e0000000-0000-0000-0000-000000000026', 3, 'SELECT ???, ???, ??? FROM clientes ORDER BY ??? ASC LIMIT 5 OFFSET 5;', 25),
('e0000000-0000-0000-0000-000000000011', 1, 'Solo debes tomar pedidos completados y calcular tres métricas globales en una única fila resumen (sin GROUP BY).', 15),
('e0000000-0000-0000-0000-000000000011', 2, 'Combina WHERE estado_pedido = ''completado'' con las funciones COUNT(*), SUM(total) y ROUND(AVG(total), 2).', 20),
('e0000000-0000-0000-0000-000000000011', 3, 'SELECT COUNT(*) AS total_pedidos, SUM(???) AS ingresos_totales, ROUND(AVG(???), 2) AS ticket_promedio FROM pedidos WHERE ??? = ''completado'';', 25),
('e0000000-0000-0000-0000-000000000027', 1, 'Agrupa el catálogo por categoría para calcular tanto el valor mínimo como el máximo dentro de cada grupo.', 15),
('e0000000-0000-0000-0000-000000000027', 2, 'Usa MIN(precio), MAX(precio) en el SELECT y agrupa con GROUP BY categoria_id.', 20),
('e0000000-0000-0000-0000-000000000027', 3, 'SELECT ???, MIN(???) AS precio_minimo, MAX(???) AS precio_maximo FROM productos GROUP BY ???;', 25),
('e0000000-0000-0000-0000-000000000028', 1, 'Agrupa los clientes por país, cuenta los registros de cada grupo y ordena poniendo los más numerosos primero.', 15),
('e0000000-0000-0000-0000-000000000028', 2, 'Usa GROUP BY pais junto a COUNT(*) AS total_clientes y ORDER BY total_clientes DESC, pais ASC.', 20),
('e0000000-0000-0000-0000-000000000028', 3, 'SELECT ???, COUNT(*) AS total_clientes FROM clientes GROUP BY ??? ORDER BY total_clientes DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000029', 1, 'Debes sumar las unidades disponibles agrupando los productos por su identificador de proveedor.', 15),
('e0000000-0000-0000-0000-000000000029', 2, 'Usa SUM(stock) AS stock_total en el SELECT y agrupa al final con GROUP BY proveedor_id.', 20),
('e0000000-0000-0000-0000-000000000029', 3, 'SELECT ???, SUM(???) AS stock_total FROM productos GROUP BY ???;', 25),
('e0000000-0000-0000-0000-000000000052', 1, 'Primero descarta con WHERE las filas que no están completadas y después agrupa por cliente para contar y sumar.', 15),
('e0000000-0000-0000-0000-000000000052', 2, 'Coloca WHERE estado_pedido = ''completado'' antes de GROUP BY cliente_id, mostrando COUNT(*) y SUM(total).', 20),
('e0000000-0000-0000-0000-000000000052', 3, 'SELECT ???, COUNT(*) AS compras_completadas, SUM(???) AS gasto_completado FROM pedidos WHERE ??? = ''completado'' GROUP BY ??? ORDER BY gasto_completado DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000032', 1, 'Agrupa todos los pedidos por estado para contar cuántos hay y sumar su importe en la misma consulta.', 15),
('e0000000-0000-0000-0000-000000000032', 2, 'Combina COUNT(*), SUM(total) y GROUP BY estado_pedido, ordenando por monto_acumulado DESC, estado_pedido ASC.', 20),
('e0000000-0000-0000-0000-000000000032', 3, 'SELECT ???, COUNT(*) AS total_pedidos, SUM(???) AS monto_acumulado FROM pedidos GROUP BY ??? ORDER BY monto_acumulado DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000079', 1, 'Mientras COUNT(*) cuenta todas las filas del grupo, COUNT(DISTINCT columna) descarta repeticiones y cuenta cuántos valores únicos existen.', 15),
('e0000000-0000-0000-0000-000000000079', 2, 'Agrupa por estado_pedido, combina COUNT(*) AS total_pedidos con COUNT(DISTINCT cliente_id) AS clientes_unicos y ordena con desempate.', 20),
('e0000000-0000-0000-0000-000000000079', 3, 'SELECT estado_pedido, COUNT(*) AS total_pedidos, COUNT(DISTINCT ???) AS clientes_unicos FROM pedidos GROUP BY ??? ORDER BY total_pedidos DESC, estado_pedido ASC;', 25),
('e0000000-0000-0000-0000-000000000004', 1, 'Primero agrupa los productos por su categoría, cuenta cuántos hay en cada grupo y luego descarta los grupos pequeños.', 15),
('e0000000-0000-0000-0000-000000000004', 2, 'Usa GROUP BY sobre la categoría y HAVING COUNT(*) > 2 después de agrupar.', 20),
('e0000000-0000-0000-0000-000000000004', 3, 'SELECT ???, COUNT(*) AS total_productos FROM productos GROUP BY ??? HAVING COUNT(*) > 2;', 25),
('e0000000-0000-0000-0000-000000000030', 1, 'Primero agrupa y suma el stock por proveedor; después filtra los grupos ya agregados que superen las 100 unidades.', 15),
('e0000000-0000-0000-0000-000000000030', 2, 'Las funciones agregadas como SUM(...) se filtran en HAVING, no en WHERE.', 20),
('e0000000-0000-0000-0000-000000000030', 3, 'SELECT ???, SUM(???) AS stock_total FROM productos GROUP BY ??? HAVING SUM(???) > 100;', 25),
('e0000000-0000-0000-0000-000000000031', 1, 'Calcula el promedio por cliente agrupando sus pedidos y quédate solo con quienes superen 500€ de media.', 15),
('e0000000-0000-0000-0000-000000000031', 2, 'Usa ROUND(AVG(total), 2) en SELECT, agrupa con GROUP BY cliente_id y filtra con HAVING AVG(total) > 500.', 20),
('e0000000-0000-0000-0000-000000000031', 3, 'SELECT ???, ROUND(AVG(???), 2) AS ticket_promedio FROM pedidos GROUP BY ??? HAVING AVG(???) > 500;', 25),
('e0000000-0000-0000-0000-000000000005', 1, 'Conecta ambas tablas por la clave que identifica al cliente en la tabla de pedidos y en el catálogo de clientes.', 15),
('e0000000-0000-0000-0000-000000000005', 2, 'Usa INNER JOIN combinando pedidos y clientes con ON sobre cliente_id, asignando alias cortos para evitar ambigüedad.', 20),
('e0000000-0000-0000-0000-000000000005', 3, 'SELECT p.pedido_id, c.nombre, c.apellido, p.total FROM pedidos p INNER JOIN clientes c ON p.??? = c.???;', 25),
('e0000000-0000-0000-0000-000000000033', 1, 'Reemplaza el identificador numérico de categoría uniendo la tabla de productos con su tabla descriptiva de categorías.', 15),
('e0000000-0000-0000-0000-000000000033', 2, 'Usa INNER JOIN categorias c ON p.categoria_id = c.categoria_id y ordena primero por nombre_categoria ASC y luego por nombre_producto ASC.', 20),
('e0000000-0000-0000-0000-000000000033', 3, 'SELECT p.producto_id, p.nombre_producto, c.nombre_categoria, p.precio FROM productos p INNER JOIN categorias c ON p.??? = c.??? ORDER BY c.nombre_categoria ASC, p.nombre_producto ASC;', 25),
('e0000000-0000-0000-0000-000000000034', 1, 'Relaciona el catálogo de artículos con la tabla de fabricantes por la clave de proveedor.', 15),
('e0000000-0000-0000-0000-000000000034', 2, 'Usa INNER JOIN proveedores pv sobre proveedor_id, renombra el país con AS pais_proveedor y ordena con desempate único.', 20),
('e0000000-0000-0000-0000-000000000034', 3, 'SELECT pr.producto_id, pr.nombre_producto, pv.nombre_proveedor, pv.pais AS pais_proveedor FROM productos pr INNER JOIN proveedores pv ON pr.??? = pv.??? ORDER BY pr.nombre_producto ASC, pr.producto_id ASC;', 25),
('e0000000-0000-0000-0000-000000000035', 1, 'Une facturas y pagos por su identificador de factura, y filtra únicamente los pagos con estado aprobado.', 15),
('e0000000-0000-0000-0000-000000000035', 2, 'Combina INNER JOIN pagos pg ON f.factura_id = pg.factura_id con WHERE pg.estado_pago = ''aprobado'' y ordena por factura_id ascendente.', 20),
('e0000000-0000-0000-0000-000000000035', 3, 'SELECT f.factura_id, f.monto_total, pg.metodo_pago, pg.fecha_pago FROM facturas f INNER JOIN pagos pg ON f.??? = pg.??? WHERE pg.estado_pago = ''aprobado'' ORDER BY f.factura_id ASC;', 25),
('e0000000-0000-0000-0000-000000000012', 1, 'Une clientes y pedidos por su identificador común e incluye en GROUP BY todas las columnas no agregadas del SELECT.', 15),
('e0000000-0000-0000-0000-000000000012', 2, 'Calcula SUM(p.total) AS total_gastado después de agrupar por c.cliente_id, c.nombre y c.apellido, y ordena con desempate único.', 20),
('e0000000-0000-0000-0000-000000000012', 3, 'SELECT c.cliente_id, c.nombre, c.apellido, SUM(p.total) AS total_gastado FROM clientes c INNER JOIN pedidos p ON c.??? = p.??? GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY total_gastado DESC, c.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000006', 1, 'Para conservar a todos los clientes aunque no tengan pedidos, la tabla de clientes debe ir a la izquierda de un LEFT JOIN.', 15),
('e0000000-0000-0000-0000-000000000006', 2, 'Cuando un cliente no tiene pedidos asociados, las columnas de pedidos quedan como NULL; filtra con WHERE ... IS NULL.', 20),
('e0000000-0000-0000-0000-000000000006', 3, 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c LEFT JOIN pedidos p ON c.??? = p.??? WHERE p.pedido_id IS NULL;', 25),
('e0000000-0000-0000-0000-000000000013', 1, 'Mantén todos los productos en el resultado usando LEFT JOIN hacia la tabla donde se registran las líneas de venta.', 15),
('e0000000-0000-0000-0000-000000000013', 2, 'Si un artículo nunca se vendió, la clave primaria de la tabla derecha valdrá NULL; evalúa esa ausencia en WHERE.', 20),
('e0000000-0000-0000-0000-000000000013', 3, 'SELECT p.producto_id, p.nombre_producto FROM productos p LEFT JOIN detalle_pedidos dp ON p.??? = dp.??? WHERE dp.detalle_id IS NULL;', 25),
('e0000000-0000-0000-0000-000000000036', 1, 'Une todas las facturas emitidas con sus posibles abonos con LEFT JOIN para no perder las que no tienen cobro.', 15),
('e0000000-0000-0000-0000-000000000036', 2, 'Filtra en WHERE las facturas cuya clave de pago derecha sea IS NULL y ordena de forma ascendente por factura_id.', 20),
('e0000000-0000-0000-0000-000000000036', 3, 'SELECT f.factura_id, f.pedido_id, f.fecha_emision, f.monto_total FROM facturas f LEFT JOIN pagos p ON f.??? = p.??? WHERE p.pago_id IS NULL ORDER BY f.factura_id ASC;', 25),
('e0000000-0000-0000-0000-000000000037', 1, 'Si filtras el almacén 1 en el WHERE perderás los productos sin inventario; coloca esa restricción dentro de la cláusula ON.', 15),
('e0000000-0000-0000-0000-000000000037', 2, 'En el ON del LEFT JOIN combina producto_id con i.almacen_id = 1, y después conserva los ausentes con WHERE i.almacen_id IS NULL.', 20),
('e0000000-0000-0000-0000-000000000037', 3, 'SELECT p.producto_id, p.nombre_producto FROM productos p LEFT JOIN inventario i ON p.??? = i.??? AND i.almacen_id = 1 WHERE i.almacen_id IS NULL ORDER BY p.producto_id ASC;', 25),
('e0000000-0000-0000-0000-000000000038', 1, 'Para que los clientes sin compras aparezcan con 0 en lugar de desaparecer, usa LEFT JOIN y evita COUNT(*).', 15),
('e0000000-0000-0000-0000-000000000038', 2, 'Cuenta explícitamente p.pedido_id con COUNT(p.pedido_id) AS total_pedidos y agrupa por las columnas del cliente.', 20),
('e0000000-0000-0000-0000-000000000038', 3, 'SELECT c.cliente_id, c.nombre, c.apellido, COUNT(p.pedido_id) AS total_pedidos FROM clientes c LEFT JOIN pedidos p ON c.??? = p.??? GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY total_pedidos DESC, c.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000053', 1, 'Al unir con LEFT JOIN, SUM() sobre filas sin pedidos devuelve NULL en lugar de cero; envuélvelo en una función de respaldo.', 15),
('e0000000-0000-0000-0000-000000000053', 2, 'Usa COALESCE(SUM(p.total), 0) AS gasto_total agrupando por las columnas del cliente y ordenando con desempate único.', 20),
('e0000000-0000-0000-0000-000000000053', 3, 'SELECT c.cliente_id, c.nombre, c.apellido, COALESCE(SUM(p.???), 0) AS gasto_total FROM clientes c LEFT JOIN pedidos p ON c.??? = p.??? GROUP BY c.cliente_id, c.nombre, c.apellido ORDER BY gasto_total DESC, c.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000014', 1, 'Traza el camino relacional paso a paso: desde el pedido hacia el cliente por un lado, y hacia sus líneas, productos y categorías por otro.', 15),
('e0000000-0000-0000-0000-000000000014', 2, 'Encadena los 4 INNER JOIN con alias cortos, renombra c.nombre AS cliente_nombre y termina con ORDER BY y LIMIT 10.', 20),
('e0000000-0000-0000-0000-000000000014', 3, 'SELECT p.pedido_id, c.nombre AS cliente_nombre, pr.nombre_producto, cat.nombre_categoria, dp.cantidad, dp.precio_unitario FROM pedidos p INNER JOIN clientes c ON p.cliente_id = c.cliente_id INNER JOIN detalle_pedidos dp ON p.??? = dp.??? INNER JOIN productos pr ON dp.??? = pr.??? INNER JOIN categorias cat ON pr.??? = cat.??? ORDER BY p.pedido_id ASC, pr.nombre_producto ASC LIMIT 10;', 25),
('e0000000-0000-0000-0000-000000000039', 1, 'Necesitas recorrer la cadena completa desde clientes hasta categorías pasando por pedidos, detalle de pedidos y productos.', 15),
('e0000000-0000-0000-0000-000000000039', 2, 'Agrupa por c.ciudad y cat.nombre_categoria, suma dp.cantidad * dp.precio_unitario como monto_vendido y ordena por ciudad ASC, monto_vendido DESC y nombre_categoria ASC.', 20),
('e0000000-0000-0000-0000-000000000039', 3, 'SELECT c.ciudad, cat.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS monto_vendido FROM clientes c INNER JOIN pedidos p ON c.cliente_id = p.cliente_id INNER JOIN detalle_pedidos dp ON p.pedido_id = dp.pedido_id INNER JOIN productos pr ON dp.producto_id = pr.producto_id INNER JOIN categorias cat ON pr.??? = cat.??? GROUP BY c.ciudad, cat.nombre_categoria ORDER BY c.ciudad ASC, monto_vendido DESC, cat.nombre_categoria ASC;', 25),
('e0000000-0000-0000-0000-000000000040', 1, 'Enlaza tres tablas en secuencia: la orden conecta con su factura y la factura conecta con su pago.', 15),
('e0000000-0000-0000-0000-000000000040', 2, 'Asigna los alias monto_factura a f.monto_total y monto_pago a pg.monto, y ordena por p.pedido_id ascendente.', 20),
('e0000000-0000-0000-0000-000000000040', 3, 'SELECT p.pedido_id, p.cliente_id, f.monto_total AS monto_factura, pg.monto AS monto_pago, pg.metodo_pago FROM pedidos p INNER JOIN facturas f ON p.??? = f.??? INNER JOIN pagos pg ON f.??? = pg.??? ORDER BY p.pedido_id ASC;', 25),
('e0000000-0000-0000-0000-000000000041', 1, 'Conecta productos con almacenes usando la tabla puente de existencias físicas y aplica el filtro de mayor a 10 unidades.', 15),
('e0000000-0000-0000-0000-000000000041', 2, 'Filtra con WHERE i.cantidad_disponible > 10 y ordena alfabéticamente por nombre_producto ASC y luego nombre_almacen ASC.', 20),
('e0000000-0000-0000-0000-000000000041', 3, 'SELECT pr.nombre_producto, a.nombre_almacen, a.ciudad, i.cantidad_disponible FROM productos pr INNER JOIN inventario i ON pr.??? = i.??? INNER JOIN almacenes a ON i.??? = a.??? WHERE i.cantidad_disponible > 10 ORDER BY pr.nombre_producto ASC, a.nombre_almacen ASC;', 25),
('e0000000-0000-0000-0000-000000000042', 1, 'Construye dos consultas SELECT independientes con la misma estructura de columnas y combínalas verticalmente con UNION.', 15),
('e0000000-0000-0000-0000-000000000042', 2, 'En cada SELECT incluye una etiqueta de texto literal con el alias tipo_entidad (''cliente'' y ''almacen'') y coloca un único ORDER BY al final.', 20),
('e0000000-0000-0000-0000-000000000042', 3, 'SELECT ciudad, ''cliente'' AS tipo_entidad FROM clientes UNION SELECT ???, ''almacen'' AS tipo_entidad FROM almacenes ORDER BY ciudad ASC, tipo_entidad ASC;', 25),
('e0000000-0000-0000-0000-000000000054', 1, 'Para hallar elementos presentes en ambos conjuntos a la vez, separa dos consultas SELECT simples con INTERSECT.', 15),
('e0000000-0000-0000-0000-000000000054', 2, 'Muestra ciudad desde la primera tabla, escribe INTERSECT, muestra ciudad desde la segunda y coloca ORDER BY ciudad ASC al final.', 20),
('e0000000-0000-0000-0000-000000000054', 3, 'SELECT ??? FROM clientes INTERSECT SELECT ??? FROM almacenes ORDER BY ciudad ASC;', 25),
('e0000000-0000-0000-0000-000000000043', 1, 'Para restar un conjunto de resultados de otro sin usar uniones, coloca el operador EXCEPT entre dos consultas SELECT equivalentes.', 15),
('e0000000-0000-0000-0000-000000000043', 2, 'Pon primero las ciudades de clientes, luego EXCEPT, luego las ciudades de almacenes y ordena el resultado alfabéticamente.', 20),
('e0000000-0000-0000-0000-000000000043', 3, 'SELECT ciudad FROM clientes EXCEPT SELECT ??? FROM almacenes ORDER BY ciudad ASC;', 25),
('e0000000-0000-0000-0000-000000000044', 1, 'Para obtener todas las combinaciones posibles entre dos catálogos independientes, CROSS JOIN no lleva condición ON.', 15),
('e0000000-0000-0000-0000-000000000044', 2, 'Conecta almacenes y categorias con CROSS JOIN y ordena por nombre_almacen ASC y nombre_categoria ASC.', 20),
('e0000000-0000-0000-0000-000000000044', 3, 'SELECT a.nombre_almacen, c.nombre_categoria FROM almacenes a CROSS JOIN categorias c ORDER BY ??? ASC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000045', 1, 'Une la tabla de productos consigo misma usando dos alias distintos (p1 y p2) para comparar parejas de la misma categoría.', 15),
('e0000000-0000-0000-0000-000000000045', 2, 'Además de igualar categoria_id, agrega p1.producto_id < p2.producto_id en el ON para evitar pares repetidos o consigo mismo.', 20),
('e0000000-0000-0000-0000-000000000045', 3, 'SELECT p1.categoria_id, p1.nombre_producto AS producto_a, p2.nombre_producto AS producto_b, p1.precio AS precio_a, p2.precio AS precio_b FROM productos p1 INNER JOIN productos p2 ON p1.categoria_id = p2.categoria_id AND p1.??? < p2.??? ORDER BY p1.categoria_id ASC, producto_a ASC, producto_b ASC;', 25),
('e0000000-0000-0000-0000-000000000015', 1, 'Calcula primero el promedio global de precios dentro de una subconsulta entre paréntesis en la cláusula WHERE.', 15),
('e0000000-0000-0000-0000-000000000015', 2, 'Compara precio > (SELECT AVG(precio) FROM productos) y ordena del más caro al más barato desempatando por nombre_producto.', 20),
('e0000000-0000-0000-0000-000000000015', 3, 'SELECT nombre_producto, precio FROM productos WHERE precio > (SELECT AVG(???) FROM productos) ORDER BY precio DESC, nombre_producto ASC;', 25),
('e0000000-0000-0000-0000-000000000046', 1, 'Genera en una subconsulta la lista de identificadores de clientes que tienen al menos un pedido de 1000€ o más.', 15),
('e0000000-0000-0000-0000-000000000046', 2, 'Usa WHERE cliente_id IN (...) sobre la subconsulta de pedidos filtrada por total >= 1000 y ordena por cliente_id ascendente.', 20),
('e0000000-0000-0000-0000-000000000046', 3, 'SELECT cliente_id, nombre, apellido, email FROM clientes WHERE cliente_id IN (SELECT ??? FROM pedidos WHERE total >= 1000) ORDER BY cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000047', 1, 'Para verificar si existe al menos un pedido completado por cada cliente sin duplicar filas, usa una subconsulta correlacionada con EXISTS.', 15),
('e0000000-0000-0000-0000-000000000047', 2, 'Dentro de EXISTS (SELECT 1 FROM pedidos p ...), conecta p.cliente_id = c.cliente_id junto con estado_pedido = ''completado''.', 20),
('e0000000-0000-0000-0000-000000000047', 3, 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c WHERE EXISTS (SELECT 1 FROM pedidos p WHERE p.??? = c.??? AND p.estado_pedido = ''completado'') ORDER BY c.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000055', 1, 'Utiliza WHERE NOT EXISTS (...) para conservar únicamente las filas de la consulta externa que no encuentren ninguna coincidencia interna.', 15),
('e0000000-0000-0000-0000-000000000055', 2, 'Dentro de la subconsulta correlaciona p.cliente_id = c.cliente_id y exige p.estado_pedido = ''completado''.', 20),
('e0000000-0000-0000-0000-000000000055', 3, 'SELECT c.cliente_id, c.nombre, c.apellido FROM clientes c WHERE NOT EXISTS (SELECT 1 FROM pedidos p WHERE p.??? = c.??? AND p.estado_pedido = ''completado'') ORDER BY c.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000016', 1, 'Evalúa los rangos de mayor a menor usando una expresión condicional CASE WHEN ... THEN ... ELSE ... END.', 15),
('e0000000-0000-0000-0000-000000000016', 2, 'Recuerda poner primero el umbral más alto (>= 1000), luego el intermedio (>= 300) y cerrar con ELSE ''Bajo Valor'' END AS segmento.', 20),
('e0000000-0000-0000-0000-000000000016', 3, 'SELECT pedido_id, total, CASE WHEN total >= 1000 THEN ''Alto Valor'' WHEN total >= 300 THEN ''Medio Valor'' ELSE ''Bajo Valor'' END AS segmento FROM pedidos ORDER BY total DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000048', 1, 'Coloca una expresión CASE dentro de cada función SUM() para acumular solo los importes que correspondan a cada estado.', 15),
('e0000000-0000-0000-0000-000000000048', 2, 'Cuando el estado no coincida devuelve 0 en el ELSE, agrupa por cliente_id y ordena de forma ascendente.', 20),
('e0000000-0000-0000-0000-000000000048', 3, 'SELECT cliente_id, SUM(CASE WHEN estado_pedido = ''completado'' THEN ??? ELSE 0 END) AS ventas_completadas, SUM(CASE WHEN estado_pedido = ''pendiente'' THEN ??? ELSE 0 END) AS ventas_pendientes FROM pedidos GROUP BY cliente_id ORDER BY cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000056', 1, 'Como COUNT() ignora los valores NULL, puedes devolver 1 en THEN cuando la condición se cumpla y omitir el ELSE (que queda NULL).', 15),
('e0000000-0000-0000-0000-000000000056', 2, 'Combina LEFT JOIN productos p, agrupa por c.categoria_id y c.nombre_categoria, y usa COUNT(CASE WHEN p.precio >= 500 THEN 1 END).', 20),
('e0000000-0000-0000-0000-000000000056', 3, 'SELECT c.nombre_categoria, COUNT(CASE WHEN p.??? >= 500 THEN 1 END) AS productos_premium, COUNT(CASE WHEN p.??? < 500 THEN 1 END) AS productos_estandar FROM categorias c LEFT JOIN productos p ON c.??? = p.??? GROUP BY c.categoria_id, c.nombre_categoria ORDER BY c.categoria_id ASC;', 25),
('e0000000-0000-0000-0000-000000000017', 1, 'Define primero el bloque temporal WITH ventas_por_categoria AS (...) cruzando categorias, productos y detalle_pedidos.', 15),
('e0000000-0000-0000-0000-000000000017', 2, 'Dentro de la CTE agrupa por c.nombre_categoria calculando SUM(dp.cantidad * dp.precio_unitario) AS facturacion, y luego consulta esa CTE.', 20),
('e0000000-0000-0000-0000-000000000017', 3, 'WITH ventas_por_categoria AS (SELECT c.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS facturacion FROM categorias c INNER JOIN productos pr ON c.categoria_id = pr.categoria_id INNER JOIN detalle_pedidos dp ON pr.producto_id = dp.producto_id GROUP BY c.nombre_categoria) SELECT nombre_categoria, facturacion FROM ventas_por_categoria ORDER BY facturacion DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000049', 1, 'Declara dos tablas temporales en una sola cláusula WITH separándolas por una coma (sin repetir WITH), donde la segunda calcule el AVG() leyendo de la primera.', 15),
('e0000000-0000-0000-0000-000000000049', 2, 'Une gasto_clientes g con la CTE escalar promedio_general p mediante CROSS JOIN (o compárala en WHERE) filtrando WHERE g.total_gastado > p.gasto_medio y ordena con desempate.', 20),
('e0000000-0000-0000-0000-000000000049', 3, 'WITH gasto_clientes AS (SELECT cliente_id, SUM(total) AS total_gastado FROM pedidos GROUP BY cliente_id), promedio_general AS (SELECT AVG(total_gastado) AS gasto_medio FROM gasto_clientes) SELECT g.cliente_id, g.total_gastado FROM gasto_clientes g CROSS JOIN promedio_general p WHERE g.total_gastado > p.??? ORDER BY g.total_gastado DESC, g.cliente_id ASC;', 25),
('e0000000-0000-0000-0000-000000000057', 1, 'Extrae el periodo mensual con TO_CHAR(fecha_pedido, ''YYYY-MM'') tanto en el SELECT como en el GROUP BY dentro de la CTE.', 15),
('e0000000-0000-0000-0000-000000000057', 2, 'Filtra primero estado_pedido = ''completado'' dentro de pedidos_mensuales y ordena la selección final por mes ASC.', 20),
('e0000000-0000-0000-0000-000000000057', 3, 'WITH pedidos_mensuales AS (SELECT TO_CHAR(fecha_pedido, ''YYYY-MM'') AS mes, COUNT(*) AS total_pedidos, SUM(???) AS ingresos_mensuales FROM pedidos WHERE ??? = ''completado'' GROUP BY TO_CHAR(fecha_pedido, ''YYYY-MM'')) SELECT mes, total_pedidos, ingresos_mensuales FROM pedidos_mensuales ORDER BY mes ASC;', 25),
('e0000000-0000-0000-0000-000000000058', 1, 'Una CTE puede referenciarse varias veces en la consulta principal: úsala tanto en el FROM como dentro de una subconsulta escalar en el WHERE.', 15),
('e0000000-0000-0000-0000-000000000058', 2, 'Compara WHERE facturacion > (SELECT AVG(facturacion) FROM facturacion_categoria) y ordena por facturacion DESC, nombre_categoria ASC.', 20),
('e0000000-0000-0000-0000-000000000058', 3, 'WITH facturacion_categoria AS (SELECT c.categoria_id, c.nombre_categoria, SUM(dp.cantidad * dp.precio_unitario) AS facturacion FROM categorias c INNER JOIN productos pr ON c.categoria_id = pr.categoria_id INNER JOIN detalle_pedidos dp ON pr.producto_id = dp.producto_id GROUP BY c.categoria_id, c.nombre_categoria) SELECT nombre_categoria, facturacion FROM facturacion_categoria WHERE facturacion > (SELECT AVG(???) FROM facturacion_categoria) ORDER BY facturacion DESC, ??? ASC;', 25),
('e0000000-0000-0000-0000-000000000007', 1, 'Utiliza la función de ventana ROW_NUMBER() acompañada de OVER (...) para numerar cada producto sin colapsar las filas.', 15),
('e0000000-0000-0000-0000-000000000007', 2, 'Dentro de OVER define ORDER BY precio DESC, producto_id ASC para desempatar precios iguales, y ordena la consulta final por ranking ASC.', 20),
('e0000000-0000-0000-0000-000000000007', 3, 'SELECT producto_id, nombre_producto, precio, ROW_NUMBER() OVER (ORDER BY precio DESC, ??? ASC) AS ranking FROM productos ORDER BY ranking ASC;', 25),
('e0000000-0000-0000-0000-000000000018', 1, 'Usa DENSE_RANK() con PARTITION BY dentro de OVER (...) para reiniciar el ranking en cada categoría sin dejar huecos ante empates.', 15),
('e0000000-0000-0000-0000-000000000018', 2, 'Particiona por categoria_id y ordena internamente por precio DESC; al final ordena por categoria_id, ranking_categoria y nombre_producto.', 20),
('e0000000-0000-0000-0000-000000000018', 3, 'SELECT categoria_id, nombre_producto, precio, DENSE_RANK() OVER (PARTITION BY ??? ORDER BY precio DESC) AS ranking_categoria FROM productos ORDER BY categoria_id ASC, ranking_categoria ASC, nombre_producto ASC;', 25),
('e0000000-0000-0000-0000-000000000059', 1, 'Las funciones de ventana no pueden filtrarse directamente en el WHERE de la misma consulta; envuélvelas primero en una CTE.', 15),
('e0000000-0000-0000-0000-000000000059', 2, 'Dentro de OVER particiona por categoria_id y ordena por precio DESC, producto_id ASC; en el SELECT externo filtra WHERE posicion = 1.', 20),
('e0000000-0000-0000-0000-000000000059', 3, 'WITH ranking_productos AS (SELECT categoria_id, nombre_producto, precio, ROW_NUMBER() OVER (PARTITION BY ??? ORDER BY precio DESC, ??? ASC) AS posicion FROM productos) SELECT categoria_id, nombre_producto, precio FROM ranking_productos WHERE posicion = 1 ORDER BY categoria_id ASC;', 25),
('e0000000-0000-0000-0000-000000000060', 1, 'Cuando SUM() lleva OVER (ORDER BY ...) se comporta como función de ventana y va sumando fila tras fila en vez de colapsar toda la tabla.', 15),
('e0000000-0000-0000-0000-000000000060', 2, 'Filtra estado_pedido = ''completado'' en WHERE y usa SUM(total) OVER (ORDER BY fecha_pedido ASC, pedido_id ASC) AS ingresos_acumulados.', 20),
('e0000000-0000-0000-0000-000000000060', 3, 'SELECT pedido_id, fecha_pedido, total, SUM(???) OVER (ORDER BY fecha_pedido ASC, ??? ASC) AS ingresos_acumulados FROM pedidos WHERE ??? = ''completado'' ORDER BY fecha_pedido ASC, pedido_id ASC;', 25),
('e0000000-0000-0000-0000-000000000050', 1, 'La función de ventana LAG() te permite leer la fecha de la fila anterior dentro de la partición de cada cliente.', 15),
('e0000000-0000-0000-0000-000000000050', 2, 'Usa PARTITION BY cliente_id y ORDER BY fecha_pedido ASC, pedido_id ASC tanto en la ventana OVER como al final de la consulta.', 20),
('e0000000-0000-0000-0000-000000000050', 3, 'SELECT pedido_id, cliente_id, fecha_pedido, LAG(fecha_pedido) OVER (PARTITION BY ??? ORDER BY fecha_pedido ASC, pedido_id ASC) AS fecha_pedido_anterior FROM pedidos ORDER BY cliente_id ASC, fecha_pedido ASC, pedido_id ASC;', 25),
('e0000000-0000-0000-0000-000000000061', 1, 'Al insertar en una tabla con clave primaria SERIAL autogenerada, enumera entre paréntesis solo las columnas de negocio y pasa sus valores en el mismo orden dentro de VALUES.', 15),
('e0000000-0000-0000-0000-000000000061', 2, 'Usa INSERT INTO categorias con las columnas (nombre_categoria, descripcion) y asigna en VALUES la nueva categoría y su detalle.', 20),
('e0000000-0000-0000-0000-000000000061', 3, 'INSERT INTO categorias (???, ???) VALUES (''Audio Profesional'', ''???'');', 25),
('e0000000-0000-0000-0000-000000000062', 1, 'PostgreSQL permite insertar múltiples filas en un solo comando separando cada grupo de paréntesis con una coma dentro de la cláusula VALUES.', 15),
('e0000000-0000-0000-0000-000000000062', 2, 'Declara INSERT INTO almacenes con las columnas (nombre_almacen, ciudad, capacidad_m2) y encadena las dos filas separadas por coma después de VALUES.', 20),
('e0000000-0000-0000-0000-000000000062', 3, 'INSERT INTO almacenes (nombre_almacen, ciudad, capacidad_m2) VALUES (''Centro Logístico Sur'', ''???'', ???), (''???'', ''Vigo'', 2400);', 25),
('e0000000-0000-0000-0000-000000000063', 1, 'En PostgreSQL no necesitas hacer un SELECT posterior para conocer el ID asignado: añade RETURNING al final del INSERT con las columnas que deseas mostrar.', 15),
('e0000000-0000-0000-0000-000000000063', 2, 'Después de VALUES (3, 5, ''Webcam 4K Studio'', 125.00, 30), agrega RETURNING producto_id, nombre_producto, precio, stock.', 20),
('e0000000-0000-0000-0000-000000000063', 3, 'INSERT INTO productos (categoria_id, proveedor_id, nombre_producto, precio, stock) VALUES (3, 5, ''Webcam 4K Studio'', 125.00, 30) RETURNING ???, nombre_producto, ???, stock;', 25),
('e0000000-0000-0000-0000-000000000064', 1, 'Cuando insertas datos provenientes de otra tabla, reemplazas la palabra VALUES por una consulta SELECT cuyas columnas coincidan en orden y tipo con las columnas destino.', 15),
('e0000000-0000-0000-0000-000000000064', 2, 'Declara INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) y acompáñalo del SELECT sobre productos filtrando categoria_id = 5 AND producto_id <> 15.', 20),
('e0000000-0000-0000-0000-000000000064', 3, 'INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) SELECT 3, ???, 12 FROM productos WHERE categoria_id = ??? AND producto_id <> 15;', 25),
('e0000000-0000-0000-0000-000000000080', 1, 'En PostgreSQL, ON CONFLICT (col1, col2) DO UPDATE intercepta colisiones de clave primaria o única y transforma la inserción en una actualización atómica.', 15),
('e0000000-0000-0000-0000-000000000080', 2, 'La tabla especial EXCLUDED contiene los valores que intentabas insertar; suma inventario.cantidad_disponible + EXCLUDED.cantidad_disponible en el SET.', 20),
('e0000000-0000-0000-0000-000000000080', 3, 'INSERT INTO inventario (almacen_id, producto_id, cantidad_disponible) VALUES (3, 15, 20) ON CONFLICT (???, ???) DO UPDATE SET cantidad_disponible = inventario.cantidad_disponible + EXCLUDED.??? RETURNING almacen_id, producto_id, cantidad_disponible;', 25),
('e0000000-0000-0000-0000-000000000065', 1, 'En toda sentencia UPDATE es indispensable incluir la cláusula WHERE para no sobrescribir todos los registros de la tabla.', 15),
('e0000000-0000-0000-0000-000000000065', 2, 'Usa UPDATE sobre la tabla proveedores, asigna la columna telefono en SET y restringe la fila con WHERE proveedor_id = 2.', 20),
('e0000000-0000-0000-0000-000000000065', 3, 'UPDATE proveedores SET ??? = ''+886-2-999888'' WHERE ??? = 2;', 25),
('e0000000-0000-0000-0000-000000000066', 1, 'En la cláusula SET puedes referenciar el valor actual de la columna (precio * 1.10) envuelto en ROUND(..., 2) y cerrar con RETURNING.', 15),
('e0000000-0000-0000-0000-000000000066', 2, 'Filtra WHERE categoria_id = 4 y añade RETURNING producto_id, nombre_producto, precio al final de la instrucción.', 20),
('e0000000-0000-0000-0000-000000000066', 3, 'UPDATE productos SET precio = ROUND(??? * 1.10, 2) WHERE categoria_id = 4 RETURNING producto_id, ???, precio;', 25),
('e0000000-0000-0000-0000-000000000067', 1, 'En PostgreSQL, cuando una actualización depende de columnas de otra tabla, se añade la cláusula FROM después de SET y se unen ambas tablas en el WHERE.', 15),
('e0000000-0000-0000-0000-000000000067', 2, 'Usa UPDATE inventario i con SET cantidad_disponible = i.cantidad_disponible + 5, incorpora FROM almacenes a y une i.almacen_id = a.almacen_id en el WHERE.', 20),
('e0000000-0000-0000-0000-000000000067', 3, 'UPDATE inventario i SET cantidad_disponible = i.cantidad_disponible + 5 FROM almacenes a WHERE i.??? = a.??? AND a.ciudad = ''Bilbao'';', 25),
('e0000000-0000-0000-0000-000000000068', 1, 'DELETE FROM elimina filas completas de una tabla, por lo que no lleva lista de columnas entre DELETE y FROM; solo requiere un WHERE preciso.', 15),
('e0000000-0000-0000-0000-000000000068', 2, 'Combina la cláusula DELETE FROM sobre detalle_pedidos con el filtro WHERE por la columna pedido_id.', 20),
('e0000000-0000-0000-0000-000000000068', 3, 'DELETE FROM ??? WHERE ??? = 105;', 25),
('e0000000-0000-0000-0000-000000000069', 1, 'En CREATE TABLE defines cada columna con su nombre, tipo de dato (SERIAL, VARCHAR(25), NUMERIC(5, 2), DATE) y restricciones (PRIMARY KEY, NOT NULL) separadas por comas.', 15),
('e0000000-0000-0000-0000-000000000069', 2, 'Asegúrate de respetar el orden: cupon_id SERIAL PRIMARY KEY, codigo VARCHAR(25) NOT NULL, descuento_pct NUMERIC(5, 2) NOT NULL, fecha_expiracion DATE NOT NULL.', 20),
('e0000000-0000-0000-0000-000000000069', 3, 'CREATE TABLE cupones_descuento (cupon_id SERIAL PRIMARY KEY, codigo VARCHAR(25) NOT NULL, descuento_pct ??? NOT NULL, fecha_expiracion ??? NOT NULL);', 25),
('e0000000-0000-0000-0000-000000000070', 1, 'Usa REFERENCES tabla(columna) para definir cada clave foránea inline y CHECK (calificacion BETWEEN 1 AND 5) para validar el rango permitido.', 15),
('e0000000-0000-0000-0000-000000000070', 2, 'Declara las 5 columnas: resena_id SERIAL PRIMARY KEY, producto_id INT NOT NULL REFERENCES productos(producto_id), cliente_id INT NOT NULL REFERENCES clientes(cliente_id), calificacion INT NOT NULL CHECK (calificacion BETWEEN 1 AND 5), comentario TEXT.', 20),
('e0000000-0000-0000-0000-000000000070', 3, 'CREATE TABLE resenas_productos (resena_id SERIAL PRIMARY KEY, producto_id INT NOT NULL REFERENCES productos(???), cliente_id INT NOT NULL REFERENCES clientes(???), calificacion INT NOT NULL CHECK (calificacion BETWEEN 1 AND 5), comentario TEXT);', 25),
('e0000000-0000-0000-0000-000000000071', 1, 'Para añadir un campo obligatorio (NOT NULL) a una tabla que ya tiene filas, debes acompañarlo de DEFAULT para que PostgreSQL rellene automáticamente los registros existentes.', 15),
('e0000000-0000-0000-0000-000000000071', 2, 'Usa ALTER TABLE sobre almacenes junto con la cláusula ADD COLUMN definiendo el tipo BOOLEAN, la restricción NOT NULL y el valor por defecto.', 20),
('e0000000-0000-0000-0000-000000000071', 3, 'ALTER TABLE almacenes ADD COLUMN ??? BOOLEAN NOT NULL DEFAULT ???;', 25),
('e0000000-0000-0000-0000-000000000072', 1, 'Cuando una tabla tiene vistas o claves foráneas que dependen de ella, DROP TABLE normal falla a menos que especifiques CASCADE al final.', 15),
('e0000000-0000-0000-0000-000000000072', 2, 'Combina DROP TABLE IF EXISTS con el nombre de la tabla heredada y cierra la instrucción con la palabra clave CASCADE.', 20),
('e0000000-0000-0000-0000-000000000072', 3, 'DROP TABLE IF EXISTS ??? CASCADE;', 25),
('e0000000-0000-0000-0000-000000000073', 1, 'La sintaxis estándar para crear un índice en PostgreSQL es CREATE INDEX nombre_indice ON nombre_tabla (columna).', 15),
('e0000000-0000-0000-0000-000000000073', 2, 'Combina CREATE INDEX con el identificador solicitado, la cláusula ON apuntando a la tabla clientes y la columna entre paréntesis.', 20),
('e0000000-0000-0000-0000-000000000073', 3, 'CREATE INDEX ??? ON clientes (???);', 25),
('e0000000-0000-0000-0000-000000000074', 1, 'Un índice único compuesto usa CREATE UNIQUE INDEX y enumera las columnas entre paréntesis en el orden de selectividad y consulta.', 15),
('e0000000-0000-0000-0000-000000000074', 2, 'Usa CREATE UNIQUE INDEX con el nombre solicitado, la cláusula ON sobre la tabla pagos y las dos columnas separadas por coma.', 20),
('e0000000-0000-0000-0000-000000000074', 3, 'CREATE UNIQUE INDEX idx_pagos_factura_metodo_unico ON ??? (???, ???);', 25),
('e0000000-0000-0000-0000-000000000075', 1, 'Un índice parcial en PostgreSQL añade una cláusula WHERE al final de la sentencia CREATE INDEX para indexar solo el subconjunto de filas activas.', 15),
('e0000000-0000-0000-0000-000000000075', 2, 'Define CREATE INDEX sobre pedidos (fecha_pedido) y añade al cierre la condición WHERE filtrando por estado_pedido.', 20),
('e0000000-0000-0000-0000-000000000075', 3, 'CREATE INDEX idx_pedidos_pendientes_fecha ON pedidos (???) WHERE ??? = ''pendiente'';', 25),
('e0000000-0000-0000-0000-000000000076', 1, 'A diferencia de otros motores, en PostgreSQL DROP INDEX no lleva ON nombre_tabla: solo requiere DROP INDEX IF EXISTS nombre_indice.', 15),
('e0000000-0000-0000-0000-000000000076', 2, 'Combina la instrucción DROP INDEX con la cláusula IF EXISTS seguida del nombre del índice redundante.', 20),
('e0000000-0000-0000-0000-000000000076', 3, 'DROP INDEX IF EXISTS ???;', 25);
